#!/usr/bin/env node
const fs=require("fs"),p=require("path");
const P1={"package.json":"{\n  \"name\": \"lfc-bot\",\n  \"version\": \"1.0.0\",\n  \"description\": \"Legacy Football Championship - Discord Bot for Roblox Football League Management\",\n  \"main\": \"dist/index.js\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"build\": \"prisma generate && tsc\",\n    \"start\": \"prisma db push && tsx src/index.ts\",\n    \"dev\": \"tsx watch src/index.ts\",\n    \"postinstall\": \"prisma generate\",\n    \"prisma:generate\": \"prisma generate\",\n    \"prisma:push\": \"prisma db push\",\n    \"prisma:migrate\": \"prisma migrate dev\",\n    \"prisma:studio\": \"prisma studio\",\n    \"deploy:commands\": \"tsx src/deploy-commands.ts\"\n  },\n  \"dependencies\": {\n    \"@prisma/client\": \"^6.6.0\",\n    \"discord.js\": \"^14.18.0\",\n    \"dotenv\": \"^16.4.7\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.13.0\",\n    \"prisma\": \"^6.6.0\",\n    \"tsx\": \"^4.19.0\",\n    \"typescript\": \"^5.7.0\"\n  }\n}",".env":"# Discord Bot\nDISCORD_TOKEN=MTUzMTQ1OTMyNDc4NDgwMzk1MA.GFgg1s.YEX-vawQ6VU1jN6IXar91L6k-HGuU-rp4cCdv8\nCLIENT_ID=1531459324784803950\nGUILD_ID=1528366297161797672\n\n# Database\nDATABASE_URL=postgresql://neondb_owner:npg_c7kYfv1nldUp@ep-late-smoke-za1jl7uh.c-2.eu-west-2.aws.neon.tech/neondb?sslmode=require\n\n# Bot Configuration\nBOT_NAME=Legacy Football Championship\nBOT_PREFIX=/","prisma/schema.prisma":"generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── USER ────────────────────────────────────────────────────────────────────\n\nmodel DiscordUser {\n  id            String   @id @default(cuid())\n  discordId     String   @unique\n  username      String\n  globalName    String?\n  avatarUrl     String?\n  joinedAt      DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  player        Player?\n  teamsManaged  Team[]    @relation(\"TeamManager\")\n  refereedMatches Match[] @relation(\"MatchReferee\")\n  warnings      Warning[]\n  suspensions   Suspension[]\n\n  @@map(\"discord_users\")\n}\n\n// ─── PLAYER ──────────────────────────────────────────────────────────────────\n\nmodel Player {\n  id            String   @id @default(cuid())\n  lfcId         String   @unique\n  discordId     String   @unique\n  robloxUsername String?  // Roblox username for verification\n  robloxId      String?   // Roblox user ID\n  nickname      String?   // Auto-nickname assigned on contract\n  position      String   // Goalkeeper, Defender, Midfielder, Forward\n  region        String   // Europe, Asia, Africa, etc.\n  joinedAt      DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  user          DiscordUser @relation(fields: [discordId], references: [discordId])\n  teamId        String?\n  team          Team?       @relation(\"TeamPlayers\", fields: [teamId], references: [id])\n  roleInTeam    String?     // Captain, Vice Captain, Starter, Sub, Academy\n\n  // Career stats\n  goals         Int      @default(0)\n  assists       Int      @default(0)\n  saves         Int      @default(0)   // Goalkeeper specific\n  mvps          Int      @default(0)\n  appearances   Int      @default(0)\n  yellowCards   Int      @default(0)\n  redCards      Int      @default(0)\n  cleanSheets   Int      @default(0)   // Goalkeeper specific\n\n  trophies      Int      @default(0)\n  awards        Award[]\n\n  // Season-specific stats\n  seasonStats   PlayerSeasonStats[]\n\n  // Match participation\n  matchGoals    MatchGoal[]\n  matchAssists  MatchAssist[]\n  matchMvps     MatchMvp[]\n\n  // Contract & transfer history\n  contracts     Contract[]\n  transfersFrom Transfer[] @relation(\"FromPlayer\")\n  transfersTo   Transfer[] @relation(\"ToPlayer\")\n\n  // Lineup participation\n  lineups       LineupPlayer[]\n\n  @@map(\"players\")\n}\n\nmodel PlayerSeasonStats {\n  id          String @id @default(cuid())\n  playerId    String\n  seasonId    String\n  goals       Int    @default(0)\n  assists     Int    @default(0)\n  saves       Int    @default(0)\n  mvps        Int    @default(0)\n  appearances Int    @default(0)\n  yellowCards Int    @default(0)\n  redCards    Int    @default(0)\n  cleanSheets Int    @default(0)\n\n  player      Player @relation(fields: [playerId], references: [id])\n  season      Season @relation(fields: [seasonId], references: [id])\n\n  @@unique([playerId, seasonId])\n  @@map(\"player_season_stats\")\n}\n\n// ─── TEAM ────────────────────────────────────────────────────────────────────\n\nmodel Team {\n  id            String      @id @default(cuid())\n  name          String      @unique\n  shortName     String?     // e.g. \"LFC\"\n  logoUrl       String?\n  description   String?\n  managerId     String\n  manager       DiscordUser @relation(\"TeamManager\", fields: [managerId], references: [id])\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n\n  players       Player[]    @relation(\"TeamPlayers\")\n\n  // Season records\n  seasonTeams   TeamSeasonStats[]\n\n  // Home and away matches\n  homeMatches   Match[]     @relation(\"HomeTeam\")\n  awayMatches   Match[]     @relation(\"AwayTeam\")\n\n  trophies      Int         @default(0)\n\n  @@map(\"teams\")\n}\n\nmodel TeamSeasonStats {\n  id          String  @id @default(cuid())\n  teamId      String\n  seasonId    String\n  played      Int     @default(0)\n  wins        Int     @default(0)\n  draws       Int     @default(0)\n  losses      Int     @default(0)\n  goalsFor    Int     @default(0)\n  goalsAgainst Int    @default(0)\n  points      Int     @default(0)\n\n  team        Team    @relation(fields: [teamId], references: [id])\n  season      Season  @relation(fields: [seasonId], references: [id])\n\n  @@unique([teamId, seasonId])\n  @@map(\"team_season_stats\")\n}\n\n// ─── SEASON ──────────────────────────────────────────────────────────────────\n\nmodel Season {\n  id          String   @id @default(cuid())\n  name        String   @unique // e.g. \"Season 1\", \"Season 2\"\n  isActive    Boolean  @default(false)\n  startedAt   DateTime?\n  endedAt     DateTime?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  matches     Match[]\n  playerStats PlayerSeasonStats[]\n  teamStats   TeamSeasonStats[]\n  awards      Award[]\n\n  @@map(\"seasons\")\n}\n\n// ─── MATCH ───────────────────────────────────────────────────────────────────\n\nmodel Match {\n  id          String   @id @default(cuid())\n  matchNumber Int?\n  matchweek   Int?      // Week/fixture number\n  homeTeamId  String\n  awayTeamId  String\n  homeScore   Int      @default(0)\n  awayScore   Int      @default(0)\n  status      String   @default(\"Scheduled\") // Scheduled, Live, Finished, Postponed, Forfeit\n  matchDate   DateTime?\n  refereeId   String?\n  referee     DiscordUser? @relation(\"MatchReferee\", fields: [refereeId], references: [id])\n  seasonId    String\n  season      Season   @relation(fields: [seasonId], references: [id])\n  threadId    String?   // Discord thread ID for live match\n  forfeit     Boolean  @default(false)\n  forfeitingTeam String? // \"home\" or \"away\" — who forfeited\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  homeTeam    Team     @relation(\"HomeTeam\", fields: [homeTeamId], references: [id])\n  awayTeam    Team     @relation(\"AwayTeam\", fields: [awayTeamId], references: [id])\n\n  goals       MatchGoal[]\n  assists     MatchAssist[]\n  mvps        MatchMvp[]\n  cards       MatchCard[]\n  lineups     Lineup[]\n  lineupsP    LineupPlayer[]\n  disputes    Dispute[]\n  predictions Prediction[]\n  motmPoll    MotmPoll[]\n  motmVotes   MotmVote[]\n\n  @@map(\"matches\")\n}\n\nmodel MatchGoal {\n  id       String @id @default(cuid())\n  matchId  String\n  playerId String\n  minute   Int?\n  isOwnGoal Boolean @default(false)\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_goals\")\n}\n\nmodel MatchAssist {\n  id       String @id @default(cuid())\n  matchId  String\n  playerId String\n  minute   Int?\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_assists\")\n}\n\nmodel MatchMvp {\n  id       String @id @default(cuid())\n  matchId  String @unique\n  playerId String\n  reason   String?\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_mvps\")\n}\n\nmodel MatchCard {\n  id       String @id @default(cuid())\n  matchId  String\n  playerId String\n  type     String // Yellow, Red\n  minute   Int?\n  reason   String?\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_cards\")\n}\n\n// ─── AWARD ───────────────────────────────────────────────────────────────────\n\nmodel Award {\n  id        String   @id @default(cuid())\n  type      String   // Golden Boot, Golden Boy, Best Playmaker, etc.\n  playerId  String\n  seasonId  String\n  reason    String?\n  awardedAt DateTime @default(now())\n\n  player    Player   @relation(fields: [playerId], references: [id])\n  season    Season   @relation(fields: [seasonId], references: [id])\n\n  @@unique([playerId, seasonId, type])\n  @@map(\"awards\")\n}\n\n// ─── TRANSFER ────────────────────────────────────────────────────────────────\n\nmodel Transfer {\n  id            String   @id @default(cuid())\n  playerId      String\n  fromTeamId    String?\n  toTeamId      String?\n  fromTeamName  String?\n  toTeamName    String?\n  fee           Int?     // Transfer fee (in millions or currency unit)\n  status        String   @default(\"Pending\") // Pending, Completed, Cancelled\n  completedAt   DateTime?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  player        Player   @relation(\"FromPlayer\", fields: [playerId], references: [id])\n\n  @@map(\"transfers\")\n}\n\n// ─── WARNINGS & SUSPENSIONS ──────────────────────────────────────────────────\n\nmodel Warning {\n  id        String   @id @default(cuid())\n  userId    String\n  reason    String\n  issuedBy  String   // Discord ID of who issued\n  createdAt DateTime @default(now())\n\n  user      DiscordUser @relation(fields: [userId], references: [id])\n\n  @@map(\"warnings\")\n}\n\nmodel Suspension {\n  id        String   @id @default(cuid())\n  userId    String\n  reason    String\n  issuedBy  String\n  expiresAt DateTime?\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user      DiscordUser @relation(fields: [userId], references: [id])\n\n  @@map(\"suspensions\")\n}\n\nmodel Blacklist {\n  id        String   @id @default(cuid())\n  discordId String   @unique\n  reason    String\n  issuedBy  String\n  createdAt DateTime @default(now())\n\n  @@map(\"blacklist\")\n}\n\n// ─── GUILD CONFIG ────────────────────────────────────────────────────────────\n\nmodel GuildConfig {\n  id          String   @id @default(cuid())\n  guildId     String   @unique\n  newsChannelId String?\n  staffRoleId   String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"guild_config\")\n}\n\n// ─── NEWS / ANNOUNCEMENTS ────────────────────────────────────────────────────\n\nmodel NewsArticle {\n  id        String   @id @default(cuid())\n  guildId   String\n  type      String   // match_result, transfer, award, season, milestone, broadcast\n  title     String\n  content   String   @db.Text\n  imageUrl  String?\n  messageId String?\n  channelId String?\n  createdAt DateTime @default(now())\n\n  @@map(\"news_articles\")\n}\n\n// ─── CONTRACT ────────────────────────────────────────────────────────────────\n\nmodel Contract {\n  id            String   @id @default(cuid())\n  playerId      String\n  teamId        String\n  teamName      String   @default(\"\")\n  roleInTeam    String?  // Captain, Vice Captain, Starter, Sub, Academy\n  signedAt      DateTime @default(now())\n  expiresAt     DateTime?\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  player        Player   @relation(fields: [playerId], references: [id])\n  team          Team     @relation(fields: [teamId], references: [id])\n\n  @@map(\"contracts\")\n}\n\n// ─── LINEUP ──────────────────────────────────────────────────────────────────\n\nmodel Lineup {\n  id            String   @id @default(cuid())\n  matchId       String\n  teamId        String\n  captainId     String?\n  formation     String?  // e.g. \"4-4-2\", \"4-3-3\"\n  submittedAt   DateTime @default(now())\n  isConfirmed   Boolean  @default(false)\n\n  match         Match    @relation(fields: [matchId], references: [id])\n  team          Team     @relation(fields: [teamId], references: [id])\n  players       LineupPlayer[]\n\n  @@map(\"lineups\")\n}\n\nmodel LineupPlayer {\n  id       String  @id @default(cuid())\n  lineupId String\n  playerId String\n  matchId  String\n  position String? // The position in the lineup (GK, LB, CB, CM, ST, etc.)\n  isBench  Boolean @default(false)\n  order    Int     @default(0) // Display order\n\n  lineup   Lineup  @relation(fields: [lineupId], references: [id])\n  player   Player  @relation(fields: [playerId], references: [id])\n  match    Match   @relation(fields: [matchId], references: [id])\n\n  @@map(\"lineup_players\")\n}\n\n// ─── DISPUTE ─────────────────────────────────────────────────────────────────\n\nmodel Dispute {\n  id            String   @id @default(cuid())\n  matchId       String\n  reporterId    String   // Discord ID\n  reason        String   @db.Text\n  evidenceUrl   String?  // Link to clip/screenshot evidence\n  status        String   @default(\"Open\") // Open, Under Review, Resolved, Dismissed\n  resolvedBy    String?  // Discord ID of who resolved\n  resolution    String?  // Resolution notes\n  ticketChannelId String? // Discord channel ID for the ticket\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  match         Match    @relation(fields: [matchId], references: [id])\n\n  @@map(\"disputes\")\n}\n\n// ─── PREDICTION ──────────────────────────────────────────────────────────────\n\nmodel Prediction {\n  id              String   @id @default(cuid())\n  matchId         String\n  userId          String   // Discord ID of predictor\n  predictedTeamId String   // Which team they predict will win (or null for draw)\n  predictedDraw   Boolean  @default(false)\n  points          Int      @default(0)\n  resolved        Boolean  @default(false)\n  createdAt       DateTime @default(now())\n\n  match           Match    @relation(fields: [matchId], references: [id])\n\n  @@unique([matchId, userId])\n  @@map(\"predictions\")\n}\n\n// ─── WEEKLY AWARDS ──────────────────────────────────────────────────────────\n\nmodel WeeklyAward {\n  id          String   @id @default(cuid())\n  type        String   // potw (Player of Week), totw (Team of Week)\n  playerId    String?\n  teamId      String?\n  seasonId    String\n  weekNumber  Int\n  reason      String?\n  awardedAt   DateTime @default(now())\n\n  season      Season   @relation(fields: [seasonId], references: [id])\n  player      Player?  @relation(fields: [playerId], references: [id])\n\n  @@map(\"weekly_awards\")\n}\n\n// ─── MOTM (Man of the Match) Poll ───────────────────────────────────────────\n\nmodel MotmPoll {\n  id        String   @id @default(cuid())\n  matchId   String   @unique\n  messageId String?  // Discord message ID of the poll\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  match     Match    @relation(fields: [matchId], references: [id])\n  votes     MotmVote[]\n\n  @@map(\"motm_polls\")\n}\n\nmodel MotmVote {\n  id        String   @id @default(cuid())\n  pollId    String\n  voterId   String   // Discord ID of voter\n  playerId  String   // Player they voted for\n  createdAt DateTime @default(now())\n\n  poll      MotmPoll @relation(fields: [pollId], references: [id])\n  player    Player   @relation(fields: [playerId], references: [id])\n\n  @@unique([pollId, voterId])\n  @@map(\"motm_votes\")\n}","src/index.ts":"import { Client, GatewayIntentBits, Collection, Events } from \"discord.js\";\nimport \"dotenv/config\";\nimport { prisma } from \"./database/prisma.js\";\nimport { loadCommands } from \"./utils/commandLoader.js\";\nimport { loadEvents } from \"./utils/eventLoader.js\";\nimport type { ExtendedClient } from \"./types/index.js\";\n\nconst client = new Client({\n  intents: [\n    GatewayIntentBits.Guilds,\n    GatewayIntentBits.GuildMembers,\n    GatewayIntentBits.GuildMessages,\n    GatewayIntentBits.MessageContent,\n  ],\n}) as ExtendedClient;\n\nclient.commands = new Collection();\n\nasync function bootstrap() {\n  try {\n    // Connect to database\n    await prisma.$connect();\n    console.log(\"[Database] Connected to PostgreSQL successfully.\");\n\n    // Load commands\n    await loadCommands(client);\n    console.log(\"[Commands] All commands loaded.\");\n\n    // Load events\n    await loadEvents(client);\n    console.log(\"[Events] All events loaded.\");\n\n    // Login to Discord\n    await client.login(process.env.DISCORD_TOKEN);\n    console.log(`[Bot] Logged in as ${client.user?.tag}`);\n  } catch (error) {\n    console.error(\"[Fatal] Failed to start bot:\", error);\n    process.exit(1);\n  }\n}\n\n// Graceful shutdown\nprocess.on(\"SIGINT\", async () => {\n  console.log(\"\\n[Shutdown] Shutting down gracefully...\");\n  await prisma.$disconnect();\n  client.destroy();\n  process.exit(0);\n});\n\nprocess.on(\"SIGTERM\", async () => {\n  console.log(\"\\n[Shutdown] Shutting down gracefully...\");\n  await prisma.$disconnect();\n  client.destroy();\n  process.exit(0);\n});\n\nbootstrap();","src/deploy-commands.ts":"import { REST, Routes } from \"discord.js\";\nimport \"dotenv/config\";\nimport { readdirSync } from \"fs\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nconst commands: unknown[] = [];\n\nasync function loadCommandsForDeploy() {\n  const commandsPath = join(__dirname, \"commands\");\n  const categories = readdirSync(commandsPath);\n\n  for (const category of categories) {\n    const categoryPath = join(commandsPath, category);\n    const stat = await import(\"fs\").then((fs) => fs.promises.stat(categoryPath));\n\n    if (!stat.isDirectory()) continue;\n\n    const commandFiles = readdirSync(categoryPath).filter(\n      (file) => file.endsWith(\".ts\") || file.endsWith(\".js\")\n    );\n\n    for (const file of commandFiles) {\n      const filePath = join(categoryPath, file);\n      try {\n        const commandModule = await import(filePath);\n        const command = commandModule.default;\n        if (command?.data) {\n          commands.push(command.data.toJSON());\n          console.log(`[Deploy] Loaded /${command.data.name}`);\n        }\n      } catch (error) {\n        console.error(`[Deploy] Failed to load ${file}:`, error);\n      }\n    }\n  }\n}\n\nasync function deploy() {\n  const token = process.env.DISCORD_TOKEN;\n  const clientId = process.env.CLIENT_ID;\n  const guildId = process.env.GUILD_ID;\n\n  if (!token || !clientId) {\n    console.error(\"Missing DISCORD_TOKEN or CLIENT_ID in environment.\");\n    process.exit(1);\n  }\n\n  await loadCommandsForDeploy();\n\n  const rest = new REST({ version: \"10\" }).setToken(token);\n\n  try {\n    console.log(`[Deploy] Registering ${commands.length} commands...`);\n\n    let data: unknown;\n\n    if (guildId) {\n      // Guild-specific (faster for development)\n      data = await rest.put(\n        Routes.applicationGuildCommands(clientId, guildId),\n        { body: commands }\n      );\n      console.log(`[Deploy] Registered ${(data as unknown[]).length} guild commands.`);\n    } else {\n      // Global commands (up to 1 hour propagation)\n      data = await rest.put(\n        Routes.applicationCommands(clientId),\n        { body: commands }\n      );\n      console.log(`[Deploy] Registered ${(data as unknown[]).length} global commands.`);\n    }\n  } catch (error) {\n    console.error(\"[Deploy] Failed:\", error);\n    process.exit(1);\n  }\n}\n\ndeploy();","src/types/index.ts":"import type {\n  Client,\n  Collection,\n  CommandInteraction,\n  SlashCommandBuilder,\n  SlashCommandSubcommandsOnlyBuilder,\n  SlashCommandOptionsOnlyBuilder,\n  PermissionResolvable,\n} from \"discord.js\";\n\nexport interface Command {\n  data:\n    | SlashCommandBuilder\n    | SlashCommandSubcommandsOnlyBuilder\n    | SlashCommandOptionsOnlyBuilder;\n  execute: (interaction: CommandInteraction) => Promise<void>;\n  cooldown?: number;\n  permissions?: PermissionResolvable[];\n  category?: string;\n}\n\nexport interface ExtendedClient extends Client {\n  commands: Collection<string, Command>;\n}\n\nexport interface PlayerStats {\n  goals: number;\n  assists: number;\n  saves: number;\n  mvps: number;\n  appearances: number;\n  yellowCards: number;\n  redCards: number;\n  cleanSheets: number;\n}\n\nexport interface SeasonStats extends PlayerStats {\n  seasonId: string;\n  seasonName: string;\n}\n\nexport interface LeagueStanding {\n  teamId: string;\n  teamName: string;\n  played: number;\n  wins: number;\n  draws: number;\n  losses: number;\n  goalsFor: number;\n  goalsAgainst: number;\n  goalDifference: number;\n  points: number;\n}\n\nexport type Position =\n  | \"Goalkeeper\"\n  | \"Defender\"\n  | \"Midfielder\"\n  | \"Forward\";\n\nexport type Region =\n  | \"Europe\"\n  | \"Asia\"\n  | \"Africa\"\n  | \"North America\"\n  | \"South America\"\n  | \"Oceania\";\n\nexport type AwardType =\n  | \"Golden Boot\"\n  | \"Golden Boy\"\n  | \"Best Playmaker\"\n  | \"Player of the Season\"\n  | \"Team of the Season\"\n  | \"Manager of the Season\"\n  | \"Golden Glove\";\n\nexport type TransferStatus = \"Pending\" | \"Completed\" | \"Cancelled\";\n\nexport type MatchStatus = \"Scheduled\" | \"Live\" | \"Finished\" | \"Postponed\" | \"Forfeit\";\n\nexport type TeamRole = \"Captain\" | \"Vice Captain\" | \"Starter\" | \"Sub\" | \"Academy\";\n\nexport type Formation = \"4-4-2\" | \"4-3-3\" | \"3-5-2\" | \"4-2-3-1\" | \"5-3-2\" | \"4-1-4-1\" | \"3-4-3\";","src/database/prisma.ts":"import { PrismaClient } from \"@prisma/client\";\n\nconst globalForPrisma = globalThis as unknown as {\n  prisma: PrismaClient | undefined;\n};\n\nexport const prisma =\n  globalForPrisma.prisma ??\n  new PrismaClient({\n    log:\n      process.env.NODE_ENV === \"development\"\n        ? [\"query\", \"warn\", \"error\"]\n        : [\"warn\", \"error\"],\n  });\n\nif (process.env.NODE_ENV !== \"production\") {\n  globalForPrisma.prisma = prisma;\n}","src/utils/commandLoader.ts":"import { readdirSync } from \"fs\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\nimport type { ExtendedClient, Command } from \"../types/index.js\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nexport async function loadCommands(client: ExtendedClient): Promise<void> {\n  const commandsPath = join(__dirname, \"..\", \"commands\");\n  const categories = readdirSync(commandsPath);\n\n  for (const category of categories) {\n    const categoryPath = join(commandsPath, category);\n    const stat = await import(\"fs\").then((fs) => fs.promises.stat(categoryPath));\n\n    if (!stat.isDirectory()) continue;\n\n    const commandFiles = readdirSync(categoryPath).filter(\n      (file) => file.endsWith(\".ts\") || file.endsWith(\".js\")\n    );\n\n    for (const file of commandFiles) {\n      const filePath = join(categoryPath, file);\n      try {\n        const commandModule = await import(filePath);\n        const command = commandModule.default as Command;\n\n        if (!command?.data?.name || !command?.execute) {\n          console.warn(`[Warning] Command at ${filePath} missing \"data\" or \"execute\".`);\n          continue;\n        }\n\n        client.commands.set(command.data.name, command);\n        console.log(`[Commands] Loaded /${command.data.name} (${category})`);\n      } catch (error) {\n        console.error(`[Error] Failed to load command at ${filePath}:`, error);\n      }\n    }\n  }\n}","src/utils/eventLoader.ts":"import { readdirSync } from \"fs\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nexport async function loadEvents(client: ExtendedClient): Promise<void> {\n  const eventsPath = join(__dirname, \"..\", \"events\");\n  const eventFiles = readdirSync(eventsPath).filter(\n    (file) => file.endsWith(\".ts\") || file.endsWith(\".js\")\n  );\n\n  for (const file of eventFiles) {\n    const filePath = join(eventsPath, file);\n    try {\n      const eventModule = await import(filePath);\n      const event = eventModule.default;\n\n      if (!event?.name || !event?.execute) {\n        console.warn(`[Warning] Event at ${filePath} missing \"name\" or \"execute\".`);\n        continue;\n      }\n\n      if (event.once) {\n        client.once(event.name, (...args: unknown[]) => event.execute(...args));\n      } else {\n        client.on(event.name, (...args: unknown[]) => event.execute(...args));\n      }\n\n      console.log(`[Events] Loaded ${event.name}`);\n    } catch (error) {\n      console.error(`[Error] Failed to load event at ${filePath}:`, error);\n    }\n  }\n}","src/utils/helpers.ts":"import {\n  EmbedBuilder,\n  ColorResolvable,\n  CommandInteraction,\n  GuildMember,\n} from \"discord.js\";\n\nconst PRIMARY_COLOR: ColorResolvable = \"#00AA00\";\nconst ERROR_COLOR: ColorResolvable = \"#FF0000\";\nconst WARNING_COLOR: ColorResolvable = \"#FFAA00\";\n\nexport function createEmbed(\n  title: string,\n  description?: string,\n  color: ColorResolvable = PRIMARY_COLOR\n): EmbedBuilder {\n  return new EmbedBuilder()\n    .setTitle(title)\n    .setDescription(description ?? null)\n    .setColor(color)\n    .setTimestamp();\n}\n\nexport function createSuccessEmbed(title: string, description?: string): EmbedBuilder {\n  return createEmbed(title, description, \"#00AA00\");\n}\n\nexport function createErrorEmbed(title: string, description?: string): EmbedBuilder {\n  return createEmbed(title, description, ERROR_COLOR);\n}\n\nexport function createWarningEmbed(title: string, description?: string): EmbedBuilder {\n  return createEmbed(title, description, WARNING_COLOR);\n}\n\nexport function getMember(interaction: CommandInteraction): GuildMember | null {\n  return interaction.member as GuildMember | null;\n}\n\nexport function formatDate(date: Date | null | undefined): string {\n  if (!date) return \"N/A\";\n  return date.toLocaleDateString(\"en-US\", {\n    year: \"numeric\",\n    month: \"short\",\n    day: \"numeric\",\n  });\n}\n\nexport function formatSeasonStats(stats: {\n  goals: number;\n  assists: number;\n  saves?: number;\n  mvps: number;\n  appearances: number;\n  yellowCards?: number;\n  redCards?: number;\n  cleanSheets?: number;\n}): string {\n  const parts = [\n    `⚽ Goals: ${stats.goals}`,\n    `🎯 Assists: ${stats.assists}`,\n    `🏆 MVPs: ${stats.mvps}`,\n    `📋 Appearances: ${stats.appearances}`,\n  ];\n  if (stats.saves !== undefined && stats.saves > 0) {\n    parts.push(`🧤 Saves: ${stats.saves}`);\n  }\n  if (stats.cleanSheets !== undefined && stats.cleanSheets > 0) {\n    parts.push(`🧹 Clean Sheets: ${stats.cleanSheets}`);\n  }\n  if (stats.yellowCards !== undefined) {\n    parts.push(`🟨 Yellow Cards: ${stats.yellowCards}`);\n  }\n  if (stats.redCards !== undefined) {\n    parts.push(`🟥 Red Cards: ${stats.redCards}`);\n  }\n  return parts.join(\"\\n\");\n}\n\nexport function generateLfcId(discordId: string): string {\n  // Generate a unique LFC ID\n  const hash = Array.from(discordId)\n    .reduce((acc, char) => acc + char.charCodeAt(0), 0)\n    .toString(16)\n    .toUpperCase()\n    .slice(0, 6);\n  return `LFC-${hash}`;\n}","src/utils/permissions.ts":"import type { CommandInteraction, GuildMember } from \"discord.js\";\n\nexport enum RoleType {\n  Founder = \"founder\",\n  LeagueManagement = \"league-management\",\n  Moderator = \"moderator\",\n  Referee = \"referee\",\n}\n\nconst ROLE_NAMES: Record<RoleType, string[]> = {\n  [RoleType.Founder]: [\"Founder\", \"Owner\", \"LFC Founder\"],\n  [RoleType.LeagueManagement]: [\"League Management\", \"League Admin\", \"Commissioner\"],\n  [RoleType.Moderator]: [\"Moderator\", \"Mod\", \"Staff\"],\n  [RoleType.Referee]: [\"Referee\", \"Match Official\", \"Ref\"],\n};\n\nexport function hasRole(\n  member: GuildMember | null,\n  roleType: RoleType\n): boolean {\n  if (!member) return false;\n  const allowedNames = ROLE_NAMES[roleType];\n  return member.roles.cache.some((role) =>\n    allowedNames.some(\n      (name) => role.name.toLowerCase() === name.toLowerCase()\n    )\n  );\n}\n\nexport function hasAnyStaffRole(member: GuildMember | null): boolean {\n  if (!member) return false;\n  return Object.values(RoleType).some((roleType) => hasRole(member, roleType));\n}\n\nexport function requireRole(roleType: RoleType) {\n  return function (interaction: CommandInteraction): boolean {\n    const member = interaction.member as GuildMember | null;\n    if (!member) return false;\n    return hasRole(member, roleType);\n  };\n}\n\nexport function getRoleHierarchy(): RoleType[] {\n  return [RoleType.Founder, RoleType.LeagueManagement, RoleType.Moderator, RoleType.Referee];\n}","src/events/ready.ts":"import { Events, ActivityType } from \"discord.js\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\nconst event = {\n  name: Events.ClientReady,\n  once: true,\n  execute(client: ExtendedClient) {\n    if (!client.user) return;\n\n    console.log(`[Bot] ${client.user.tag} is online!`);\n    console.log(`[Bot] Serving ${client.guilds.cache.size} guilds`);\n\n    // Set bot activity\n    client.user.setActivity(\"Legacy Football Championship\", {\n      type: ActivityType.Watching,\n    });\n\n    // Set bot status\n    client.user.setStatus(\"online\");\n  },\n};\n\nexport default event;","src/events/interactionCreate.ts":"import { Events, CommandInteraction, GuildMember } from \"discord.js\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\nconst event = {\n  name: Events.InteractionCreate,\n  async execute(interaction: CommandInteraction) {\n    // Handle slash commands only\n    if (!interaction.isChatInputCommand()) return;\n\n    const client = interaction.client as ExtendedClient;\n    const command = client.commands.get(interaction.commandName);\n\n    if (!command) {\n      await interaction.reply({\n        content: \"❌ Command not found.\",\n        ephemeral: true,\n      });\n      return;\n    }\n\n    // Cooldown check\n    const cooldownKey = `${interaction.user.id}-${command.data.name}`;\n    const cooldownAmount = (command.cooldown ?? 3) * 1000;\n    const now = Date.now();\n\n    // Simple in-memory cooldown\n    if (!(\"cooldowns\" in client)) {\n      (client as Record<string, unknown>).cooldowns = new Map();\n    }\n    const cooldowns = (client as Record<string, unknown>).cooldowns as Map<string, number>;\n\n    if (cooldowns.has(cooldownKey)) {\n      const expiration = cooldowns.get(cooldownKey)!;\n      if (now < expiration) {\n        const timeLeft = ((expiration - now) / 1000).toFixed(1);\n        await interaction.reply({\n          content: `⏳ Please wait ${timeLeft}s before using \\`/${command.data.name}\\` again.`,\n          ephemeral: true,\n        });\n        return;\n      }\n    }\n\n    // Permission check if specified\n    if (command.permissions && command.permissions.length > 0) {\n      const member = interaction.member as GuildMember | null;\n      if (member) {\n        const hasPerms = command.permissions.every((perm) =>\n          member.permissions.has(perm)\n        );\n        if (!hasPerms) {\n          await interaction.reply({\n            content: \"❌ You don't have permission to use this command.\",\n            ephemeral: true,\n          });\n          return;\n        }\n      }\n    }\n\n    // Execute the command\n    try {\n      await command.execute(interaction);\n    } catch (error) {\n      console.error(`[Error] Command /${command.data.name}:`, error);\n\n      const reply = {\n        content: \"❌ An error occurred while executing this command.\",\n        ephemeral: true,\n      };\n\n      if (interaction.replied || interaction.deferred) {\n        await interaction.followUp(reply);\n      } else {\n        await interaction.reply(reply);\n      }\n    }\n\n    // Set cooldown\n    cooldowns.set(cooldownKey, now + cooldownAmount);\n  },\n};\n\nexport default event;","src/services/playerService.ts":"import { prisma } from \"../database/prisma.js\";\nimport { generateLfcId } from \"../utils/helpers.js\";\nimport type { Position, Region } from \"../types/index.js\";\n\nexport class PlayerService {\n  /**\n   * Get or create a player profile linked to a Discord user.\n   */\n  async getOrCreatePlayer(discordId: string, username: string) {\n    // First ensure the DiscordUser exists\n    let discordUser = await prisma.discordUser.findUnique({\n      where: { discordId },\n    });\n\n    if (!discordUser) {\n      discordUser = await prisma.discordUser.create({\n        data: { discordId, username },\n      });\n    } else if (discordUser.username !== username) {\n      // Update username if changed\n      discordUser = await prisma.discordUser.update({\n        where: { discordId },\n        data: { username },\n      });\n    }\n\n    // Check if player exists\n    let player = await prisma.player.findUnique({\n      where: { discordId },\n      include: {\n        user: true,\n        team: true,\n        seasonStats: { include: { season: true } },\n        awards: { include: { season: true } },\n      },\n    });\n\n    if (!player) {\n      player = await prisma.player.create({\n        data: {\n          lfcId: generateLfcId(discordId),\n          discordId,\n          position: \"Midfielder\",\n          region: \"Europe\",\n        },\n        include: {\n          user: true,\n          team: true,\n          seasonStats: { include: { season: true } },\n          awards: { include: { season: true } },\n        },\n      });\n    }\n\n    return player;\n  }\n\n  /**\n   * Get a player by Discord ID.\n   */\n  async getPlayer(discordId: string) {\n    return prisma.player.findUnique({\n      where: { discordId },\n      include: {\n        user: true,\n        team: true,\n        seasonStats: {\n          include: { season: true },\n          orderBy: { season: { name: \"desc\" } },\n        },\n        awards: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * Get a player by LFC ID.\n   */\n  async getPlayerByLfcId(lfcId: string) {\n    return prisma.player.findUnique({\n      where: { lfcId },\n      include: {\n        user: true,\n        team: true,\n        seasonStats: {\n          include: { season: true },\n          orderBy: { season: { name: \"desc\" } },\n        },\n        awards: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * Update player position and region.\n   */\n  async updatePlayerProfile(\n    discordId: string,\n    data: { position?: Position; region?: Region }\n  ) {\n    return prisma.player.update({\n      where: { discordId },\n      data,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get top goalscorers.\n   */\n  async getTopGoalscorers(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { goals: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get top assist providers.\n   */\n  async getTopAssists(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { assists: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get most MVPs.\n   */\n  async getTopMvps(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { mvps: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get most appearances.\n   */\n  async getTopAppearances(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { appearances: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get transfer history for a player.\n   */\n  async getTransferHistory(playerId: string) {\n    return prisma.transfer.findMany({\n      where: { playerId, status: \"Completed\" },\n      orderBy: { completedAt: \"desc\" },\n    });\n  }\n}\n\nexport const playerService = new PlayerService();","src/services/teamService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class TeamService {\n  /**\n   * Create a new team.\n   */\n  async createTeam(data: {\n    name: string;\n    shortName?: string;\n    description?: string;\n    managerId: string;\n  }) {\n    return prisma.team.create({\n      data: {\n        name: data.name,\n        shortName: data.shortName,\n        description: data.description,\n        managerId: data.managerId,\n      },\n      include: { manager: true },\n    });\n  }\n\n  /**\n   * Get a team by ID.\n   */\n  async getTeamById(teamId: string) {\n    return prisma.team.findUnique({\n      where: { id: teamId },\n      include: {\n        manager: true,\n        players: { include: { user: true } },\n        seasonTeams: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * Get a team by name.\n   */\n  async getTeamByName(name: string) {\n    return prisma.team.findUnique({\n      where: { name },\n      include: {\n        manager: true,\n        players: { include: { user: true } },\n        seasonTeams: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * List all teams.\n   */\n  async listTeams() {\n    return prisma.team.findMany({\n      include: {\n        manager: true,\n        _count: { select: { players: true } },\n      },\n      orderBy: { name: \"asc\" },\n    });\n  }\n\n  /**\n   * Get team stats for a specific season.\n   */\n  async getTeamSeasonStats(teamId: string, seasonId: string) {\n    return prisma.teamSeasonStats.findUnique({\n      where: { teamId_seasonId: { teamId, seasonId } },\n    });\n  }\n\n  /**\n   * Add a player to a team.\n   */\n  async addPlayerToTeam(playerId: string, teamId: string) {\n    return prisma.player.update({\n      where: { id: playerId },\n      data: { teamId },\n    });\n  }\n\n  /**\n   * Remove a player from their team.\n   */\n  async removePlayerFromTeam(playerId: string) {\n    return prisma.player.update({\n      where: { id: playerId },\n      data: { teamId: null },\n    });\n  }\n}\n\nexport const teamService = new TeamService();","src/services/matchService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class MatchService {\n  /**\n   * Create a new match.\n   */\n  async createMatch(data: {\n    homeTeamId: string;\n    awayTeamId: string;\n    seasonId: string;\n    matchDate?: Date;\n    refereeId?: string;\n  }) {\n    return prisma.match.create({\n      data: {\n        homeTeamId: data.homeTeamId,\n        awayTeamId: data.awayTeamId,\n        seasonId: data.seasonId,\n        matchDate: data.matchDate,\n        refereeId: data.refereeId,\n        status: \"Scheduled\",\n      },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n      },\n    });\n  }\n\n  /**\n   * Start a match (set status to Live).\n   */\n  async startMatch(matchId: string) {\n    return prisma.match.update({\n      where: { id: matchId },\n      data: { status: \"Live\" },\n    });\n  }\n\n  /**\n   * Finish a match with a score.\n   */\n  async finishMatch(\n    matchId: string,\n    data: {\n      homeScore: number;\n      awayScore: number;\n    }\n  ) {\n    const match = await prisma.match.update({\n      where: { id: matchId },\n      data: {\n        homeScore: data.homeScore,\n        awayScore: data.awayScore,\n        status: \"Finished\",\n      },\n    });\n\n    // Update team season stats\n    await this.updateTeamStatsAfterMatch(match);\n\n    return match;\n  }\n\n  /**\n   * Update team standings after a match finishes.\n   */\n  private async updateTeamStatsAfterMatch(match: {\n    id: string;\n    homeTeamId: string;\n    awayTeamId: string;\n    homeScore: number;\n    awayScore: number;\n    seasonId: string;\n  }) {\n    const homeStats = await prisma.teamSeasonStats.findUnique({\n      where: {\n        teamId_seasonId: {\n          teamId: match.homeTeamId,\n          seasonId: match.seasonId,\n        },\n      },\n    });\n\n    const awayStats = await prisma.teamSeasonStats.findUnique({\n      where: {\n        teamId_seasonId: {\n          teamId: match.awayTeamId,\n          seasonId: match.seasonId,\n        },\n      },\n    });\n\n    // Determine result\n    let homeResult: \"win\" | \"draw\" | \"loss\";\n    let awayResult: \"win\" | \"draw\" | \"loss\";\n\n    if (match.homeScore > match.awayScore) {\n      homeResult = \"win\";\n      awayResult = \"loss\";\n    } else if (match.homeScore < match.awayScore) {\n      homeResult = \"loss\";\n      awayResult = \"win\";\n    } else {\n      homeResult = \"draw\";\n      awayResult = \"draw\";\n    }\n\n    // Update home team stats\n    if (homeStats) {\n      await prisma.teamSeasonStats.update({\n        where: { id: homeStats.id },\n        data: {\n          played: homeStats.played + 1,\n          wins: homeStats.wins + (homeResult === \"win\" ? 1 : 0),\n          draws: homeStats.draws + (homeResult === \"draw\" ? 1 : 0),\n          losses: homeStats.losses + (homeResult === \"loss\" ? 1 : 0),\n          goalsFor: homeStats.goalsFor + match.homeScore,\n          goalsAgainst: homeStats.goalsAgainst + match.awayScore,\n          points:\n            homeStats.points +\n            (homeResult === \"win\" ? 3 : homeResult === \"draw\" ? 1 : 0),\n        },\n      });\n    }\n\n    // Update away team stats\n    if (awayStats) {\n      await prisma.teamSeasonStats.update({\n        where: { id: awayStats.id },\n        data: {\n          played: awayStats.played + 1,\n          wins: awayStats.wins + (awayResult === \"win\" ? 1 : 0),\n          draws: awayStats.draws + (awayResult === \"draw\" ? 1 : 0),\n          losses: awayStats.losses + (awayResult === \"loss\" ? 1 : 0),\n          goalsFor: awayStats.goalsFor + match.awayScore,\n          goalsAgainst: awayStats.goalsAgainst + match.homeScore,\n          points:\n            awayStats.points +\n            (awayResult === \"win\" ? 3 : awayResult === \"draw\" ? 1 : 0),\n        },\n      });\n    }\n  }\n\n  /**\n   * Record a goal in a match.\n   */\n  async recordGoal(matchId: string, playerId: string, minute?: number) {\n    const goal = await prisma.matchGoal.create({\n      data: { matchId, playerId, minute },\n    });\n\n    // Increment player goals\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { goals: { increment: 1 } },\n    });\n\n    return goal;\n  }\n\n  /**\n   * Record an assist in a match.\n   */\n  async recordAssist(matchId: string, playerId: string, minute?: number) {\n    const assist = await prisma.matchAssist.create({\n      data: { matchId, playerId, minute },\n    });\n\n    // Increment player assists\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { assists: { increment: 1 } },\n    });\n\n    return assist;\n  }\n\n  /**\n   * Record a card in a match.\n   */\n  async recordCard(\n    matchId: string,\n    playerId: string,\n    type: \"Yellow\" | \"Red\",\n    minute?: number,\n    reason?: string\n  ) {\n    const card = await prisma.matchCard.create({\n      data: { matchId, playerId, type, minute, reason },\n    });\n\n    // Increment player cards\n    const field = type === \"Yellow\" ? \"yellowCards\" : \"redCards\";\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { [field]: { increment: 1 } },\n    });\n\n    return card;\n  }\n\n  /**\n   * Record MVP for a match.\n   */\n  async recordMvp(matchId: string, playerId: string, reason?: string) {\n    const mvp = await prisma.matchMvp.upsert({\n      where: { matchId },\n      update: { playerId, reason },\n      create: { matchId, playerId, reason },\n    });\n\n    // Increment player MVPs\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { mvps: { increment: 1 } },\n    });\n\n    return mvp;\n  }\n\n  /**\n   * Get matches for a team.\n   */\n  async getTeamMatches(teamId: string) {\n    return prisma.match.findMany({\n      where: {\n        OR: [{ homeTeamId: teamId }, { awayTeamId: teamId }],\n      },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n      },\n      orderBy: { matchDate: \"desc\" },\n    });\n  }\n\n  /**\n   * Get upcoming fixtures.\n   */\n  async getUpcomingFixtures(limit = 10) {\n    return prisma.match.findMany({\n      where: { status: \"Scheduled\" },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n      },\n      orderBy: { matchDate: \"asc\" },\n      take: limit,\n    });\n  }\n\n  /**\n   * Get recent results.\n   */\n  async getRecentResults(limit = 10) {\n    return prisma.match.findMany({\n      where: { status: \"Finished\" },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n        goals: { include: { player: { include: { user: true } } } },\n        mvps: { include: { player: { include: { user: true } } } },\n      },\n      orderBy: { updatedAt: \"desc\" },\n      take: limit,\n    });\n  }\n}\n\nexport const matchService = new MatchService();","src/services/leagueService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class LeagueService {\n  /**\n   * Get the current active season.\n   */\n  async getActiveSeason() {\n    return prisma.season.findFirst({\n      where: { isActive: true },\n      include: {\n        _count: { select: { matches: true } },\n      },\n    });\n  }\n\n  /**\n   * Get a season by ID.\n   */\n  async getSeasonById(seasonId: string) {\n    return prisma.season.findUnique({\n      where: { id: seasonId },\n      include: {\n        _count: { select: { matches: true } },\n      },\n    });\n  }\n\n  /**\n   * Get standings for a season, sorted by points descending.\n   */\n  async getStandings(seasonId: string) {\n    const teamStats = await prisma.teamSeasonStats.findMany({\n      where: { seasonId },\n      include: { team: true },\n      orderBy: [{ points: \"desc\" }, { goalsFor: \"desc\" }],\n    });\n\n    return teamStats.map((stat, index) => ({\n      position: index + 1,\n      teamId: stat.teamId,\n      teamName: stat.team.name,\n      played: stat.played,\n      wins: stat.wins,\n      draws: stat.draws,\n      losses: stat.losses,\n      goalsFor: stat.goalsFor,\n      goalsAgainst: stat.goalsAgainst,\n      goalDifference: stat.goalsFor - stat.goalsAgainst,\n      points: stat.points,\n    }));\n  }\n\n  /**\n   * Create a new season.\n   */\n  async createSeason(name: string) {\n    return prisma.season.create({\n      data: { name, isActive: true },\n    });\n  }\n\n  /**\n   * End the current active season.\n   */\n  async endActiveSeason() {\n    const activeSeason = await this.getActiveSeason();\n    if (!activeSeason) return null;\n\n    return prisma.season.update({\n      where: { id: activeSeason.id },\n      data: {\n        isActive: false,\n        endedAt: new Date(),\n      },\n    });\n  }\n\n  /**\n   * Initialize season stats for all teams.\n   */\n  async initializeSeasonStats(seasonId: string) {\n    const teams = await prisma.team.findMany();\n    const stats = [];\n\n    for (const team of teams) {\n      const existing = await prisma.teamSeasonStats.findUnique({\n        where: {\n          teamId_seasonId: { teamId: team.id, seasonId },\n        },\n      });\n\n      if (!existing) {\n        const stat = await prisma.teamSeasonStats.create({\n          data: { teamId: team.id, seasonId },\n        });\n        stats.push(stat);\n      }\n    }\n\n    return stats;\n  }\n\n  /**\n   * Initialize season stats for all players in a team.\n   */\n  async initializePlayerSeasonStats(seasonId: string, teamId?: string) {\n    const whereClause = teamId ? { teamId } : {};\n    const players = await prisma.player.findMany({ where: whereClause });\n    const stats = [];\n\n    for (const player of players) {\n      const existing = await prisma.playerSeasonStats.findUnique({\n        where: {\n          playerId_seasonId: { playerId: player.id, seasonId },\n        },\n      });\n\n      if (!existing) {\n        const stat = await prisma.playerSeasonStats.create({\n          data: { playerId: player.id, seasonId },\n        });\n        stats.push(stat);\n      }\n    }\n\n    return stats;\n  }\n}\n\nexport const leagueService = new LeagueService();","src/services/adminService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class AdminService {\n  /**\n   * Issue a warning to a user.\n   */\n  async warnUser(discordId: string, reason: string, issuedBy: string) {\n    return prisma.warning.create({\n      data: { userId: discordId, reason, issuedBy },\n    });\n  }\n\n  /**\n   * Get warnings for a user.\n   */\n  async getUserWarnings(discordId: string) {\n    return prisma.warning.findMany({\n      where: { userId: discordId },\n      orderBy: { createdAt: \"desc\" },\n    });\n  }\n\n  /**\n   * Suspend a user.\n   */\n  async suspendUser(\n    discordId: string,\n    reason: string,\n    issuedBy: string,\n    expiresAt?: Date\n  ) {\n    return prisma.suspension.create({\n      data: {\n        userId: discordId,\n        reason,\n        issuedBy,\n        expiresAt,\n        active: true,\n      },\n    });\n  }\n\n  /**\n   * Check if a user is currently suspended.\n   */\n  async isUserSuspended(discordId: string): Promise<boolean> {\n    const suspension = await prisma.suspension.findFirst({\n      where: {\n        userId: discordId,\n        active: true,\n        OR: [\n          { expiresAt: null },\n          { expiresAt: { gte: new Date() } },\n        ],\n      },\n    });\n\n    if (!suspension) return false;\n\n    // Auto-expire if past expiry date\n    if (suspension.expiresAt && suspension.expiresAt < new Date()) {\n      await prisma.suspension.update({\n        where: { id: suspension.id },\n        data: { active: false },\n      });\n      return false;\n    }\n\n    return true;\n  }\n\n  /**\n   * Lift a suspension.\n   */\n  async liftSuspension(discordId: string) {\n    return prisma.suspension.updateMany({\n      where: { userId: discordId, active: true },\n      data: { active: false },\n    });\n  }\n\n  /**\n   * Blacklist a user.\n   */\n  async blacklistUser(discordId: string, reason: string, issuedBy: string) {\n    return prisma.blacklist.create({\n      data: { discordId, reason, issuedBy },\n    });\n  }\n\n  /**\n   * Check if a user is blacklisted.\n   */\n  async isBlacklisted(discordId: string): Promise<boolean> {\n    const entry = await prisma.blacklist.findUnique({\n      where: { discordId },\n    });\n    return !!entry;\n  }\n\n  /**\n   * Get active suspensions.\n   */\n  async getActiveSuspensions() {\n    return prisma.suspension.findMany({\n      where: { active: true },\n      include: { user: true },\n      orderBy: { createdAt: \"desc\" },\n    });\n  }\n}\n\nexport const adminService = new AdminService();","src/services/newsService.ts":"import {\n  EmbedBuilder,\n  TextChannel,\n  Guild,\n  Message,\n  hyperlink,\n} from \"discord.js\";\nimport { prisma } from \"../database/prisma.js\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\ntype NewsType =\n  | \"match_result\"\n  | \"transfer\"\n  | \"award\"\n  | \"season_start\"\n  | \"season_end\"\n  | \"milestone\"\n  | \"broadcast\"\n  | \"weekly_roundup\";\n\ninterface NewsPayload {\n  type: NewsType;\n  guildId: string;\n  title: string;\n  content: string;\n  embeds?: EmbedBuilder[];\n  imageUrl?: string;\n}\n\nexport class NewsService {\n  /**\n   * Get the configured news channel for a guild.\n   */\n  async getNewsChannel(guild: Guild): Promise<TextChannel | null> {\n    const config = await prisma.guildConfig.findUnique({\n      where: { guildId: guild.id },\n    });\n\n    if (!config?.newsChannelId) return null;\n\n    const channel = guild.channels.cache.get(config.newsChannelId);\n    if (channel instanceof TextChannel) return channel;\n\n    // Try fetching if not cached\n    try {\n      const fetched = await guild.channels.fetch(config.newsChannelId);\n      if (fetched instanceof TextChannel) return fetched;\n    } catch {\n      return null;\n    }\n\n    return null;\n  }\n\n  /**\n   * Set the news channel for a guild.\n   */\n  async setNewsChannel(guildId: string, channelId: string) {\n    return prisma.guildConfig.upsert({\n      where: { guildId },\n      update: { newsChannelId: channelId },\n      create: { guildId, newsChannelId: channelId },\n    });\n  }\n\n  /**\n   * Publish a news article to the configured channel and database.\n   */\n  async publish(client: ExtendedClient, payload: NewsPayload): Promise<Message | null> {\n    const guild = client.guilds.cache.get(payload.guildId);\n    if (!guild) return null;\n\n    const channel = await this.getNewsChannel(guild);\n    if (!channel) return null;\n\n    const embed = new EmbedBuilder()\n      .setTitle(payload.title)\n      .setDescription(payload.content)\n      .setColor(this.getColorForType(payload.type))\n      .setFooter({\n        text: `Legacy Football Championship • ${new Date().toLocaleDateString(\"en-US\", { weekday: \"long\", year: \"numeric\", month: \"long\", day: \"numeric\" })}`,\n      })\n      .setTimestamp();\n\n    // If additional embeds were provided, use the first one instead\n    const finalEmbeds = payload.embeds ?? [embed];\n\n    if (payload.imageUrl) {\n      finalEmbeds[0]?.setImage(payload.imageUrl);\n    }\n\n    // Send to channel\n    const message = await channel.send({ embeds: finalEmbeds });\n\n    // Store in database\n    await prisma.newsArticle.create({\n      data: {\n        guildId: payload.guildId,\n        type: payload.type,\n        title: payload.title,\n        content: payload.content,\n        messageId: message.id,\n        channelId: channel.id,\n      },\n    });\n\n    return message;\n  }\n\n  /**\n   * Auto-post a match result.\n   */\n  async announceMatchResult(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      homeTeam: string;\n      awayTeam: string;\n      homeScore: number;\n      awayScore: number;\n      scorers?: string[];\n      mvp?: string;\n      matchId: string;\n    }\n  ) {\n    const isDraw = data.homeScore === data.awayScore;\n    const homeWin = data.homeScore > data.awayScore;\n\n    const emoji = isDraw ? \"🤝\" : homeWin ? \"🏠\" : \"🚗\";\n    const resultText = isDraw\n      ? \"Draw!\"\n      : homeWin\n        ? `${data.homeTeam} wins!`\n        : `${data.awayTeam} wins!`;\n\n    const embed = new EmbedBuilder()\n      .setTitle(`⚽ Full-Time: ${data.homeTeam} vs ${data.awayTeam}`)\n      .setColor(isDraw ? \"#FFAA00\" : homeWin ? \"#00AA00\" : \"#0066CC\")\n      .setDescription(\n        `**${data.homeTeam}** ${data.homeScore} - ${data.awayScore} **${data.awayTeam}**\\n\\n${emoji} **${resultText}**`\n      )\n      .addFields(\n        {\n          name: \"⚽ Scorers\",\n          value: data.scorers?.length\n            ? data.scorers.join(\"\\n\")\n            : \"No goals recorded\",\n          inline: true,\n        },\n        {\n          name: \"🏆 MVP\",\n          value: data.mvp ?? \"Not selected\",\n          inline: true,\n        }\n      )\n      .setFooter({\n        text: `Match ID: ${data.matchId.slice(0, 8)} • Legacy Football Championship`,\n      })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"match_result\",\n      guildId: data.guildId,\n      title: `⚽ Match Result: ${data.homeTeam} ${data.homeScore} - ${data.awayScore} ${data.awayTeam}`,\n      content: `${emoji} **${resultText}**\\n\\n**${data.homeTeam}** ${data.homeScore} - ${data.awayScore} **${data.awayTeam}**`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Auto-post a transfer announcement.\n   */\n  async announceTransfer(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      playerName: string;\n      fromTeam: string;\n      toTeam: string;\n      fee?: string;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"🔄 Transfer Complete!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `**${data.playerName}** has completed a move!`\n      )\n      .addFields(\n        { name: \"➡️ From\", value: data.fromTeam, inline: true },\n        { name: \"🏠 To\", value: data.toTeam, inline: true },\n        {\n          name: \"💰 Fee\",\n          value: data.fee ?? \"Free Transfer\",\n          inline: true,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Transfer Window\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"transfer\",\n      guildId: data.guildId,\n      title: `🔄 ${data.playerName} joins ${data.toTeam}`,\n      content: `${data.playerName} has moved from ${data.fromTeam} to ${data.toTeam}${data.fee ? ` for ${data.fee}` : \" on a free transfer\"}.`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Auto-post an award announcement.\n   */\n  async announceAward(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      playerName: string;\n      awardType: string;\n      season: string;\n      reason?: string;\n    }\n  ) {\n    const awardEmojis: Record<string, string> = {\n      \"Golden Boot\": \"🥾\",\n      \"Golden Boy\": \"🌟\",\n      \"Best Playmaker\": \"🎯\",\n      \"Player of the Season\": \"👑\",\n      \"Team of the Season\": \"🏅\",\n      \"Manager of the Season\": \"📋\",\n    };\n\n    const emoji = awardEmojis[data.awardType] ?? \"🏅\";\n\n    const embed = new EmbedBuilder()\n      .setTitle(`${emoji} ${data.awardType} Awarded!`)\n      .setColor(\"#FFD700\")\n      .setDescription(\n        `**${data.playerName}** has been awarded **${data.awardType}**!`\n      )\n      .addFields(\n        { name: \"🏅 Award\", value: data.awardType, inline: true },\n        { name: \"📅 Season\", value: data.season, inline: true },\n        { name: \"📝 Reason\", value: data.reason ?? \"Outstanding performance\", inline: false }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Awards\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"award\",\n      guildId: data.guildId,\n      title: `${emoji} ${data.awardType}: ${data.playerName}`,\n      content: `**${data.playerName}** has won the **${data.awardType}** award for ${data.season}!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce season start.\n   */\n  async announceSeasonStart(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      seasonName: string;\n      teamCount: number;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"📅 New Season Begins!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `**${data.seasonName}** is officially underway!`\n      )\n      .addFields(\n        { name: \"📋 Season\", value: data.seasonName, inline: true },\n        { name: \"🏟️ Teams\", value: `${data.teamCount} teams competing`, inline: true },\n        {\n          name: \"🎯 What to Expect\",\n          value: [\n            \"• Exciting matches every week\",\n            \"• Intense title race\",\n            \"• Individual awards up for grabs\",\n            \"• Transfer window action\",\n          ].join(\"\\n\"),\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"season_start\",\n      guildId: data.guildId,\n      title: `📅 ${data.seasonName} has begun!`,\n      content: `The **${data.seasonName}** of Legacy Football Championship is now LIVE with **${data.teamCount} teams** competing for glory!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce season end with champion.\n   */\n  async announceSeasonEnd(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      seasonName: string;\n      championName?: string;\n      championPoints?: number;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"🏆 Season Over!\")\n      .setColor(\"#FFD700\")\n      .setDescription(`**${data.seasonName}** has concluded!`);\n\n    if (data.championName) {\n      embed.addFields(\n        {\n          name: \"👑 Champions\",\n          value: `**${data.championName}**${data.championPoints ? ` — ${data.championPoints} points` : \"\"}`,\n          inline: false,\n        },\n        {\n          name: \"🎊 Congratulations!\",\n          value: `A huge congratulations to **${data.championName}** for winning ${data.seasonName}!`,\n          inline: false,\n        }\n      );\n    }\n\n    embed\n      .addFields({\n        name: \"🏅 Awards Ceremony\",\n        value: \"Use `/award give` to distribute season awards before the next season begins.\",\n        inline: false,\n      })\n      .setFooter({ text: \"Legacy Football Championship\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"season_end\",\n      guildId: data.guildId,\n      title: `🏆 ${data.seasonName} has ended!`,\n      content: data.championName\n        ? `**${data.championName}** are the champions of ${data.seasonName}!`\n        : `${data.seasonName} has come to a close.`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce a player milestone.\n   */\n  async announceMilestone(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      playerName: string;\n      teamName?: string;\n      milestone: string; // e.g. \"10 Goals\", \"50 Appearances\", \"5 MVPs\"\n      stat: string;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"🌟 Milestone Achieved!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `**${data.playerName}** has reached a career milestone!`\n      )\n      .addFields(\n        { name: \"👤 Player\", value: data.playerName, inline: true },\n        { name: \"🎯 Milestone\", value: data.milestone, inline: true },\n        {\n          name: \"🏠 Team\",\n          value: data.teamName ?? \"Free Agent\",\n          inline: true,\n        },\n        {\n          name: \"📈 Career Stats\",\n          value: data.stat,\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Milestones\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"milestone\",\n      guildId: data.guildId,\n      title: `🌟 ${data.playerName} — ${data.milestone}!`,\n      content: `**${data.playerName}** has achieved **${data.milestone}** in their LFC career!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce a breaking news broadcast from management.\n   */\n  async announceBroadcast(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      title: string;\n      message: string;\n      authorName: string;\n      color?: string;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(`📢 ${data.title}`)\n      .setColor((data.color as never) ?? \"#FF0000\")\n      .setDescription(data.message)\n      .setFooter({\n        text: `Posted by ${data.authorName} • Legacy Football Championship`,\n      })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"broadcast\",\n      guildId: data.guildId,\n      title: `📢 ${data.title}`,\n      content: data.message,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Generate a weekly roundup embed.\n   */\n  async generateWeeklyRoundup(\n    client: ExtendedClient,\n    guildId: string,\n    seasonName: string,\n    standings: Array<{\n      position: number;\n      teamName: string;\n      played: number;\n      wins: number;\n      draws: number;\n      losses: number;\n      points: number;\n    }>,\n    topScorers: Array<{\n      name: string;\n      goals: number;\n      team?: string;\n    }>,\n    recentMatches: Array<{\n      homeTeam: string;\n      awayTeam: string;\n      homeScore: number;\n      awayScore: number;\n    }>\n  ) {\n    // Build standings snippet\n    const top3 = standings.slice(0, 3);\n    const standingsText = top3.length\n      ? top3\n          .map(\n            (s) =>\n              `${getMedalEmoji(s.position)} **${s.teamName}** — ${s.points}pts (${s.wins}W / ${s.draws}D / ${s.losses}L)`\n          )\n          .join(\"\\n\")\n      : \"No standings data yet.\";\n\n    // Build scorers snippet\n    const scorersText = topScorers.length\n      ? topScorers\n          .slice(0, 5)\n          .map((s, i) => `${i + 1}. **${s.name}**${s.team ? ` (${s.team})` : \"\"} — ${s.goals}G`)\n          .join(\"\\n\")\n      : \"No scorers data yet.\";\n\n    // Build results snippet\n    const resultsText = recentMatches.length\n      ? recentMatches\n          .slice(0, 5)\n          .map((m) => `**${m.homeTeam}** ${m.homeScore} - ${m.awayScore} **${m.awayTeam}**`)\n          .join(\"\\n\")\n      : \"No recent matches.\";\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"📊 Weekly Roundup\")\n      .setColor(\"#00AA00\")\n      .setDescription(`**${seasonName}** — Weekly summary of league action.`)\n      .addFields(\n        {\n          name: \"🏆 Top 3 Standings\",\n          value: standingsText,\n          inline: false,\n        },\n        {\n          name: \"⚽ Top Goalscorers\",\n          value: scorersText,\n          inline: true,\n        },\n        {\n          name: \"📋 Recent Results\",\n          value: resultsText,\n          inline: true,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Weekly Roundup\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"weekly_roundup\",\n      guildId,\n      title: \"📊 Weekly Roundup\",\n      content: `Here's your weekly roundup of **${seasonName}** action!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Get news history for a guild.\n   */\n  async getRecentNews(guildId: string, limit = 10) {\n    return prisma.newsArticle.findMany({\n      where: { guildId },\n      orderBy: { createdAt: \"desc\" },\n      take: limit,\n    });\n  }\n\n  /**\n   * Check and announce player milestones.\n   * Called after a match updates player stats.\n   */\n  async checkMilestones(\n    client: ExtendedClient,\n    guildId: string,\n    playerId: string\n  ) {\n    const player = await prisma.player.findUnique({\n      where: { id: playerId },\n      include: { user: true, team: true },\n    });\n\n    if (!player) return;\n\n    const milestones: Array<{ name: string; threshold: number; format: string }> = [\n      { name: \"Goals\", threshold: 10, format: `${player.goals} Goals` },\n      { name: \"Goals\", threshold: 25, format: `${player.goals} Goals` },\n      { name: \"Goals\", threshold: 50, format: `${player.goals} Goals` },\n      { name: \"Assists\", threshold: 10, format: `${player.assists} Assists` },\n      { name: \"Assists\", threshold: 25, format: `${player.assists} Assists` },\n      { name: \"MVPs\", threshold: 5, format: `${player.mvps} MVPs` },\n      { name: \"MVPs\", threshold: 10, format: `${player.mvps} MVPs` },\n      { name: \"Appearances\", threshold: 10, format: `${player.appearances} Appearances` },\n      { name: \"Appearances\", threshold: 25, format: `${player.appearances} Appearances` },\n      { name: \"Appearances\", threshold: 50, format: `${player.appearances} Appearances` },\n      { name: \"Appearances\", threshold: 100, format: `${player.appearances} Appearances` },\n    ];\n\n    for (const milestone of milestones) {\n      const current =\n        milestone.name === \"Goals\"\n          ? player.goals\n          : milestone.name === \"Assists\"\n            ? player.assists\n            : milestone.name === \"MVPs\"\n              ? player.mvps\n              : player.appearances;\n\n      if (current === milestone.threshold) {\n        // Check if we already announced this milestone\n        const alreadyAnnounced = await prisma.newsArticle.findFirst({\n          where: {\n            guildId,\n            type: \"milestone\",\n            content: { contains: `${milestone.format}` },\n            title: { contains: player.user.username },\n          },\n        });\n\n        if (!alreadyAnnounced) {\n          const statLine = `⚽ ${player.goals}G | 🎯 ${player.assists}A | 🏆 ${player.mvps} MVP | 📋 ${player.appearances} Apps`;\n          await this.announceMilestone(client, {\n            guildId,\n            playerName: player.user.username,\n            teamName: player.team?.name,\n            milestone: milestone.format,\n            stat: statLine,\n          });\n        }\n      }\n    }\n  }\n\n  private getColorForType(type: NewsType): number {\n    const colors: Record<NewsType, number> = {\n      match_result: 0x00aa00,\n      transfer: 0x0099ff,\n      award: 0xffd700,\n      season_start: 0x00aa00,\n      season_end: 0xffd700,\n      milestone: 0x00aaff,\n      broadcast: 0xff0000,\n      weekly_roundup: 0x00aa00,\n    };\n    return colors[type] ?? 0x00aa00;\n  }\n}\n\nfunction getMedalEmoji(position: number): string {\n  switch (position) {\n    case 1:\n      return \"🥇\";\n    case 2:\n      return \"🥈\";\n    case 3:\n      return \"🥉\";\n    default:\n      return \"#\";\n  }\n}\n\nexport const newsService = new NewsService();","src/services/contractService.ts":"import { prisma } from \"../database/prisma.js\";\nimport { generateLfcId } from \"../utils/helpers.js\";\nimport type { TeamRole } from \"../types/index.js\";\n\nexport class ContractService {\n  /**\n   * Offer a contract to a player — creates player if new, signs contract, assigns nickname.\n   */\n  async offerContract(data: {\n    discordId: string;\n    username: string;\n    teamName: string;\n    position: string;\n    region: string;\n    robloxUsername?: string;\n    roleInTeam?: TeamRole;\n    nickname?: string;\n  }) {\n    // 1. Ensure DiscordUser exists\n    let discordUser = await prisma.discordUser.findUnique({\n      where: { discordId: data.discordId },\n    });\n    if (!discordUser) {\n      discordUser = await prisma.discordUser.create({\n        data: { discordId: data.discordId, username: data.username },\n      });\n    }\n\n    // 2. Find team\n    const team = await prisma.team.findUnique({ where: { name: data.teamName } });\n    if (!team) throw new Error(`Team \"${data.teamName}\" not found.`);\n\n    // 3. Upsert player\n    let player = await prisma.player.findUnique({\n      where: { discordId: data.discordId },\n    });\n    if (!player) {\n      player = await prisma.player.create({\n        data: {\n          lfcId: generateLfcId(data.discordId),\n          discordId: data.discordId,\n          position: data.position,\n          region: data.region,\n          robloxUsername: data.robloxUsername,\n          nickname: data.nickname,\n          roleInTeam: data.roleInTeam,\n          teamId: team.id,\n        },\n      });\n    } else {\n      player = await prisma.player.update({\n        where: { discordId: data.discordId },\n        data: {\n          position: data.position,\n          region: data.region,\n          robloxUsername: data.robloxUsername,\n          nickname: data.nickname,\n          roleInTeam: data.roleInTeam,\n          teamId: team.id,\n        },\n      });\n    }\n\n    // 4. Deactivate any existing active contracts\n    await prisma.contract.updateMany({\n      where: { playerId: player.id, isActive: true },\n      data: { isActive: false },\n    });\n\n    // 5. Create new contract\n    const contract = await prisma.contract.create({\n      data: {\n        playerId: player.id,\n        teamId: team.id,\n        teamName: team.name,\n        roleInTeam: data.roleInTeam,\n        isActive: true,\n      },\n    });\n\n    const updatedPlayer = await prisma.player.findUnique({\n      where: { id: player.id },\n      include: { user: true, team: true },\n    });\n\n    return { player: updatedPlayer!, contract, team };\n  }\n\n  /**\n   * Release a player from their team (back to free agency).\n   */\n  async releasePlayer(discordId: string) {\n    const player = await prisma.player.findUnique({\n      where: { discordId },\n      include: { team: true, contracts: { where: { isActive: true } } },\n    });\n    if (!player) throw new Error(\"Player not found.\");\n    if (!player.teamId) throw new Error(\"Player is already a free agent.\");\n\n    // Deactivate active contracts\n    await prisma.contract.updateMany({\n      where: { playerId: player.id, isActive: true },\n      data: { isActive: false },\n    });\n\n    // Remove from team\n    await prisma.player.update({\n      where: { id: player.id },\n      data: { teamId: null, roleInTeam: null },\n    });\n\n    return player;\n  }\n\n  /**\n   * Get all free agents (verified players without a team).\n   */\n  async getFreeAgents() {\n    return prisma.player.findMany({\n      where: { teamId: null },\n      include: { user: true },\n      orderBy: { goals: \"desc\" },\n    });\n  }\n\n  /**\n   * Get a player's current contract.\n   */\n  async getActiveContract(playerId: string) {\n    return prisma.contract.findFirst({\n      where: { playerId, isActive: true },\n      include: { team: true },\n    });\n  }\n\n  /**\n   * Get all players for a team with their roles.\n   */\n  async getTeamRoster(teamId: string) {\n    return prisma.player.findMany({\n      where: { teamId },\n      include: { user: true },\n      orderBy: [{ roleInTeam: \"asc\" }, { goals: \"desc\" }],\n    });\n  }\n}\n\nexport const contractService = new ContractService();","src/services/predictionService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class PredictionService {\n  /**\n   * Place a prediction on a match.\n   */\n  async predict(data: {\n    matchId: string;\n    userId: string;\n    teamId?: string;\n    draw?: boolean;\n  }) {\n    return prisma.prediction.upsert({\n      where: {\n        matchId_userId: { matchId: data.matchId, userId: data.userId },\n      },\n      update: {\n        predictedTeamId: data.teamId ?? null,\n        predictedDraw: data.draw ?? false,\n      },\n      create: {\n        matchId: data.matchId,\n        userId: data.userId,\n        predictedTeamId: data.teamId ?? null,\n        predictedDraw: data.draw ?? false,\n      },\n    });\n  }\n\n  /**\n   * Resolve predictions after a match ends.\n   * Points: 3 for correct winner, 1 for correct draw.\n   */\n  async resolvePredictions(matchId: string) {\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n    });\n    if (!match || match.status !== \"Finished\") return;\n    if (match.homeScore === null || match.awayScore === null) return;\n\n    const predictions = await prisma.prediction.findMany({\n      where: { matchId, resolved: false },\n    });\n\n    let winnerId: string | null = null;\n    let isDraw = false;\n\n    if (match.homeScore > match.awayScore) {\n      winnerId = match.homeTeamId;\n    } else if (match.awayScore > match.homeScore) {\n      winnerId = match.awayTeamId;\n    } else {\n      isDraw = true;\n    }\n\n    for (const pred of predictions) {\n      let points = 0;\n      if (isDraw && pred.predictedDraw) points = 3;\n      else if (winnerId && pred.predictedTeamId === winnerId) points = 3;\n\n      await prisma.prediction.update({\n        where: { id: pred.id },\n        data: { points, resolved: true },\n      });\n    }\n  }\n\n  /**\n   * Get prediction leaderboard for a season.\n   */\n  async getLeaderboard(seasonId: string) {\n    const matches = await prisma.match.findMany({\n      where: { seasonId, status: \"Finished\" },\n      select: { id: true },\n    });\n    const matchIds = matches.map((m) => m.id);\n\n    const predictions = await prisma.prediction.findMany({\n      where: { matchId: { in: matchIds }, resolved: true },\n    });\n\n    // Aggregate by user\n    const userPoints = new Map<string, number>();\n    for (const p of predictions) {\n      userPoints.set(p.userId, (userPoints.get(p.userId) ?? 0) + p.points);\n    }\n\n    return Array.from(userPoints.entries())\n      .map(([userId, points]) => ({ userId, points }))\n      .sort((a, b) => b.points - a.points);\n  }\n\n  /**\n   * Get total predictions for a user.\n   */\n  async getUserStats(userId: string) {\n    const predictions = await prisma.prediction.findMany({\n      where: { userId },\n      include: { match: { include: { homeTeam: true, awayTeam: true } } },\n      orderBy: { createdAt: \"desc\" },\n    });\n\n    const correct = predictions.filter((p) => p.resolved && p.points > 0).length;\n    const total = predictions.filter((p) => p.resolved).length;\n\n    return { predictions, correct, total, accuracy: total > 0 ? ((correct / total) * 100).toFixed(1) : \"0\" };\n  }\n}\n\nexport const predictionService = new PredictionService();","src/commands/offer/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, TeamRole } from \"../../types/index.js\";\n\nconst POSITIONS = [\n  { name: \"🧤 Goalkeeper\", value: \"Goalkeeper\" },\n  { name: \"🛡️ Defender\", value: \"Defender\" },\n  { name: \"🎯 Midfielder\", value: \"Midfielder\" },\n  { name: \"⚽ Forward\", value: \"Forward\" },\n];\n\nconst ROLES = [\n  { name: \"👑 Captain\", value: \"Captain\" },\n  { name: \"⭐ Vice Captain\", value: \"Vice Captain\" },\n  { name: \"🏃 Starter\", value: \"Starter\" },\n  { name: \"🔄 Sub\", value: \"Sub\" },\n  { name: \"📚 Academy\", value: \"Academy\" },\n];\n\nconst REGIONS = [\n  { name: \"🌍 Europe\", value: \"Europe\" },\n  { name: \"🌏 Asia\", value: \"Asia\" },\n  { name: \"🌍 Africa\", value: \"Africa\" },\n  { name: \"🌎 North America\", value: \"North America\" },\n  { name: \"🌎 South America\", value: \"South America\" },\n  { name: \"🌏 Oceania\", value: \"Oceania\" },\n];\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"offer\")\n    .setDescription(\"Offer a contract to a player and auto-nickname them (Management only)\")\n    .addUserOption((opt) =>\n      opt.setName(\"player\").setDescription(\"Player to offer contract\").setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"team\").setDescription(\"Team name\").setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"position\").setDescription(\"Position\").setRequired(true)\n        .addChoices(...POSITIONS)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"region\").setDescription(\"Region\").setRequired(true)\n        .addChoices(...REGIONS)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"role\").setDescription(\"Team role\").setRequired(false)\n        .addChoices(...ROLES)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"roblox\").setDescription(\"Roblox username\").setRequired(false)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"nickname\").setDescription(\"Server nickname to assign\").setRequired(false)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) &&\n        !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Insufficient Permissions\",\"You need **Founder** or **League Management** role.\")],\n      });\n      return;\n    }\n\n    const target = interaction.options.getUser(\"player\", true);\n    const teamName = interaction.options.getString(\"team\", true);\n    const position = interaction.options.getString(\"position\", true);\n    const region = interaction.options.getString(\"region\", true);\n    const role = interaction.options.getString(\"role\") as TeamRole | null;\n    const roblox = interaction.options.getString(\"roblox\");\n    const nickname = interaction.options.getString(\"nickname\");\n\n    try {\n      const { player, contract, team } = await contractService.offerContract({\n        discordId: target.id,\n        username: target.username,\n        teamName,\n        position,\n        region,\n        robloxUsername: roblox ?? undefined,\n        roleInTeam: role ?? undefined,\n        nickname: nickname ?? undefined,\n      });\n\n      // Auto-nickname if provided\n      let nicknameResult = \"None\";\n      if (nickname && interaction.guild) {\n        try {\n          const member = await interaction.guild.members.fetch(target.id);\n          await member.setNickname(nickname);\n          nicknameResult = `✅ Set to **${nickname}**`;\n        } catch {\n          nicknameResult = \"⚠️ Could not set nickname (check bot permissions)\";\n        }\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📝 Contract Offered!\")\n        .setColor(\"#00AA00\")\n        .setDescription(`**${target.username}** has joined **${team.name}**!`)\n        .addFields(\n          { name: \"👤 Player\", value: `<@${target.id}>`, inline: true },\n          { name: \"🏟️ Team\", value: team.name, inline: true },\n          { name: \"⚽ Position\", value: position, inline: true },\n          { name: \"🌍 Region\", value: region, inline: true },\n          { name: \"🎭 Role\", value: role ?? \"Starter\", inline: true },\n          { name: \"🆔 LFC ID\", value: player.lfcId, inline: true },\n          { name: \"🎮 Roblox\", value: roblox ?? \"Not set\", inline: true },\n          { name: \"📛 Nickname\", value: nicknameResult, inline: false },\n        )\n        .setFooter({ text: `Contract ID: ${contract.id.slice(0, 8)} • Legacy Football Championship` })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error: unknown) {\n      const msg = error instanceof Error ? error.message : \"Unknown error\";\n      await interaction.editReply({ content: `❌ ${msg}` });\n    }\n  },\n};\n\nexport default command;","src/commands/release/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"release\")\n    .setDescription(\"Release a player from their team back to free agency (Management only)\")\n    .addUserOption((opt) =>\n      opt.setName(\"player\").setDescription(\"Player to release\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) &&\n        !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Insufficient Permissions\",\"You need **Founder** or **League Management** role.\")],\n      });\n      return;\n    }\n\n    const target = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await contractService.releasePlayer(target.id);\n      const embed = new EmbedBuilder()\n        .setTitle(\"🆓 Player Released\")\n        .setColor(\"#FFAA00\")\n        .setDescription(`**${target.username}** has been released from **${player.team?.name ?? \"their club\"}** and is now a free agent.`)\n        .addFields(\n          { name: \"👤 Player\", value: `<@${target.id}>`, inline: true },\n          { name: \"📊 Status\", value: \"🆓 Free Agent\", inline: true },\n          { name: \"⚽ Career Stats\", value: `${player.goals}G / ${player.assists}A / ${player.appearances} Apps`, inline: false },\n        )\n        .setFooter({ text: \"Legacy Football Championship • Transfers\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error: unknown) {\n      const msg = error instanceof Error ? error.message : \"Unknown error\";\n      await interaction.editReply({ content: `❌ ${msg}` });\n    }\n  },\n};\n\nexport default command;","src/commands/freeagents/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"freeagents\")\n    .setDescription(\"List all available free agents (unassigned players)\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const freeAgents = await contractService.getFreeAgents();\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🆓 Free Agents\")\n      .setColor(\"#00AA00\");\n\n    if (freeAgents.length === 0) {\n      embed.setDescription(\"No free agents available. All players are under contract.\");\n    } else {\n      // Group by position\n      const grouped: Record<string, typeof freeAgents> = {};\n      for (const p of freeAgents) {\n        if (!grouped[p.position]) grouped[p.position] = [];\n        grouped[p.position].push(p);\n      }\n\n      for (const [pos, players] of Object.entries(grouped)) {\n        const emojis: Record<string, string> = {\n          Goalkeeper: \"🧤\", Defender: \"🛡️\", Midfielder: \"🎯\", Forward: \"⚽\",\n        };\n        embed.addFields({\n          name: `${emojis[pos] ?? \"👤\"} ${pos}s (${players.length})`,\n          value: players\n            .slice(0, 8)\n            .map((p) =>\n              `**${p.user.username}** — ⚽${p.goals}G / 🎯${p.assists}A / 📋${p.appearances}Apps`\n            )\n            .join(\"\\n\") + (players.length > 8 ? `\\n*+${players.length - 8} more...*` : \"\"),\n          inline: false,\n        });\n      }\n    }\n\n    embed\n      .setFooter({ text: `Total: ${freeAgents.length} free agents • Use /offer to sign` })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/profile/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { formatDate, formatSeasonStats } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"profile\")\n    .setDescription(\"View a unified player profile with Roblox info and season stats\")\n    .addUserOption((opt) =>\n      opt.setName(\"player\").setDescription(\"Player to view\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const target = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await playerService.getPlayer(target.id);\n      if (!player) {\n        await interaction.editReply({\n          content: `❌ ${target.username} is not registered as an LFC player.`,\n        });\n        return;\n      }\n\n      const contract = await contractService.getActiveContract(player.id);\n\n      // Build season stats string\n      const activeStat = player.seasonStats.find((s) => s.season.isActive);\n      const seasonLine = activeStat\n        ? formatSeasonStats({\n            goals: activeStat.goals,\n            assists: activeStat.assists,\n            saves: activeStat.saves,\n            mvps: activeStat.mvps,\n            appearances: activeStat.appearances,\n            yellowCards: activeStat.yellowCards,\n            redCards: activeStat.redCards,\n            cleanSheets: activeStat.cleanSheets,\n          })\n        : \"No active season data.\";\n\n      const embed = new EmbedBuilder()\n        .setTitle(`👤 ${target.username} — Player Profile`)\n        .setThumbnail(target.displayAvatarURL())\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: \"🆔 Identity\",\n            value: [\n              `**LFC ID:** ${player.lfcId}`,\n              `**Discord:** ${target.username}`,\n              player.robloxUsername ? `**Roblox:** ${player.robloxUsername}` : null,\n              `**Joined:** ${formatDate(player.joinedAt)}`,\n            ].filter(Boolean).join(\"\\n\"),\n            inline: true,\n          },\n          {\n            name: \"⚽ Football\",\n            value: [\n              `**Club:** ${player.team?.name ?? \"🆓 Free Agent\"}`,\n              `**Position:** ${player.position}`,\n              `**Region:** ${player.region}`,\n              player.nickname ? `**Nickname:** ${player.nickname}` : null,\n            ].filter(Boolean).join(\"\\n\"),\n            inline: true,\n          },\n          {\n            name: \"🎭 Team Role\",\n            value: player.roleInTeam ?? \"Unassigned\",\n            inline: true,\n          },\n          {\n            name: \"📈 Active Season Stats\",\n            value: seasonLine,\n            inline: false,\n          },\n          {\n            name: \"🏆 Career Totals\",\n            value: formatSeasonStats({\n              goals: player.goals,\n              assists: player.assists,\n              saves: player.saves,\n              mvps: player.mvps,\n              appearances: player.appearances,\n              yellowCards: player.yellowCards,\n              redCards: player.redCards,\n              cleanSheets: player.cleanSheets,\n            }),\n            inline: false,\n          },\n          {\n            name: \"📋 Contract\",\n            value: contract\n              ? `**${contract.team.name}** — ${contract.roleInTeam ?? \"Starter\"}\\nSigned: ${formatDate(contract.signedAt)}`\n              : \"No active contract\",\n            inline: false,\n          },\n        )\n        .setFooter({ text: `Trophies: ${player.trophies} 🏆 | Legacy Football Championship` })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Profile Error]\", error);\n      await interaction.editReply({ content: \"❌ An error occurred.\" });\n    }\n  },\n};\n\nexport default command;","src/commands/topscorers/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"topscorers\")\n    .setDescription(\"View the top goalscorers leaderboard\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const players = await playerService.getTopGoalscorers(15);\n    const embed = new EmbedBuilder()\n      .setTitle(\"⚽ Top Goalscorers\")\n      .setColor(\"#FFD700\")\n      .setDescription(players.length\n        ? players.map((p, i) =>\n            `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.goals}G**`)\n          .join(\"\\n\")\n        : \"No data yet.\"\n      )\n      .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/topassists/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"topassists\")\n    .setDescription(\"View the top assists leaderboard\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const players = await playerService.getTopAssists(15);\n    const embed = new EmbedBuilder()\n      .setTitle(\"🎯 Top Assists\")\n      .setColor(\"#00AAFF\")\n      .setDescription(players.length\n        ? players.map((p, i) =>\n            `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.assists}A**`)\n          .join(\"\\n\")\n        : \"No data yet.\"\n      )\n      .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/topsaves/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"topsaves\")\n    .setDescription(\"View the top saves leaderboard (Goalkeepers)\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const players = await prisma.player.findMany({\n      where: { position: \"Goalkeeper\" },\n      orderBy: { saves: \"desc\" },\n      take: 15,\n      include: { user: true, team: true },\n    });\n    const embed = new EmbedBuilder()\n      .setTitle(\"🧤 Top Saves\")\n      .setColor(\"#00AA00\")\n      .setDescription(players.length\n        ? players.map((p, i) =>\n            `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.saves} saves** | 🧹 ${p.cleanSheets} CS`)\n          .join(\"\\n\")\n        : \"No goalkeeper data yet.\"\n      )\n      .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/leaderboards/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  StringSelectMenuBuilder,\n  ComponentType,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst BOARDS = [\n  { label: \"⚽ Golden Boot (Goals)\", value: \"goals\", emoji: \"⚽\" },\n  { label: \"🎯 Playmaker (Assists)\", value: \"assists\", emoji: \"🎯\" },\n  { label: \"🧤 Golden Glove (Saves)\", value: \"saves\", emoji: \"🧤\" },\n  { label: \"🏆 Most MVPs\", value: \"mvps\", emoji: \"🏆\" },\n  { label: \"📋 Most Appearances\", value: \"apps\", emoji: \"📋\" },\n  { label: \"🔮 Prediction King\", value: \"predictions\", emoji: \"🔮\" },\n];\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"leaderboards\")\n    .setDescription(\"View all award rankings in one place with a dropdown\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    await showBoard(interaction, \"goals\");\n  },\n};\n\nasync function showBoard(interaction: CommandInteraction, type: string) {\n  let embed: EmbedBuilder;\n\n  switch (type) {\n    case \"assists\": {\n      const players = await playerService.getTopAssists(10);\n      embed = makeBoardEmbed(\"🎯 Playmaker Rankings — Top Assists\", \"#00AAFF\", players, \"assists\", \"A\");\n      break;\n    }\n    case \"saves\": {\n      const players = await prisma.player.findMany({ where: { position: \"Goalkeeper\" }, orderBy: { saves: \"desc\" }, take: 10, include: { user: true, team: true } });\n      embed = new EmbedBuilder().setTitle(\"🧤 Golden Glove — Top Saves\").setColor(\"#00AA00\")\n        .setDescription(players.length ? players.map((p, i) => `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.saves} saves** | 🧹 ${p.cleanSheets} CS`).join(\"\\n\") : \"No data.\")\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    case \"mvps\": {\n      const players = await playerService.getTopMvps(10);\n      embed = makeBoardEmbed(\"🏆 Most Valuable Players — Top MVPs\", \"#FFD700\", players, \"mvps\", \"MVP\");\n      break;\n    }\n    case \"apps\": {\n      const players = await playerService.getTopAppearances(10);\n      embed = makeBoardEmbed(\"📋 Iron Men — Most Appearances\", \"#00AA00\", players, \"appearances\", \"Apps\");\n      break;\n    }\n    case \"predictions\": {\n      const season = await leagueService.getActiveSeason();\n      const list = season ? await predictionService.getLeaderboard(season.id) : [];\n      embed = new EmbedBuilder().setTitle(\"🔮 Prediction King\").setColor(\"#FF6600\")\n        .setDescription(list.length\n          ? list.slice(0, 10).map((u, i) => `${i + 1}. <@${u.userId}> — **${u.points} pts**`).join(\"\\n\")\n          : \"No predictions yet. Use `/predict` on matches!\")\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    default: {\n      const players = await playerService.getTopGoalscorers(10);\n      embed = makeBoardEmbed(\"⚽ Golden Boot — Top Goalscorers\", \"#FFD700\", players, \"goals\", \"G\");\n    }\n  }\n\n  const select = new StringSelectMenuBuilder()\n    .setCustomId(\"lb_select\").setPlaceholder(\"Switch leaderboard...\")\n    .addOptions(BOARDS.map((b) => ({ label: b.label, value: b.value })));\n\n  const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select);\n  const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n  const collector = reply.createMessageComponentCollector({ componentType: ComponentType.StringSelect, time: 120_000 });\n  collector.on(\"collect\", async (si) => {\n    if (si.user.id !== interaction.user.id) { await si.reply({ content: \"❌ Not your menu.\", ephemeral: true }); return; }\n    await si.deferUpdate();\n    await showBoard(si as unknown as CommandInteraction, si.values[0]);\n  });\n  collector.on(\"end\", async () => {\n    const dr = ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n    dr.components.forEach((c) => c.setDisabled(true));\n    await interaction.editReply({ components: [dr] });\n  });\n}\n\nfunction makeBoardEmbed(title: string, color: string, players: Array<{ user: { username: string; globalName: string | null }; team: { name: string } | null; goals: number; assists: number; mvps: number; appearances: number }>, key: string, suffix: string) {\n  return new EmbedBuilder().setTitle(title).setColor(color as never)\n    .setDescription(players.length\n      ? players.map((p, i) => `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${(p as Record<string, number>)[key] ?? 0}${suffix}**`).join(\"\\n\")\n      : \"No data.\")\n    .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n}\n\nexport default command;","src/commands/squad/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport type { Command, Position } from \"../../types/index.js\";\n\nconst POSITION_ORDER: Position[] = [\"Goalkeeper\", \"Defender\", \"Midfielder\", \"Forward\"];\nconst POS_EMOJIS: Record<string, string> = { Goalkeeper: \"🧤\", Defender: \"🛡️\", Midfielder: \"🎯\", Forward: \"⚽\" };\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"squad\")\n    .setDescription(\"Display a club's full roster\")\n    .addStringOption((opt) =>\n      opt.setName(\"team\").setDescription(\"Team name\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"team\", true);\n    const team = await teamService.getTeamByName(teamName);\n    if (!team) {\n      await interaction.editReply({ content: `❌ Team **${teamName}** not found.` });\n      return;\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(`👥 ${team.name} — Full Squad`)\n      .setColor(\"#00AA00\")\n      .setDescription(\n        team.players.length\n          ? `**Manager:** <@${team.manager.discordId}> | **Total:** ${team.players.length} players`\n          : \"No players registered.\"\n      );\n\n    // Group by role then position\n    const captains = team.players.filter((p) => p.roleInTeam === \"Captain\" || p.roleInTeam === \"Vice Captain\");\n    const starters = team.players.filter((p) => p.roleInTeam === \"Starter\" || !p.roleInTeam);\n    const subs = team.players.filter((p) => p.roleInTeam === \"Sub\" || p.roleInTeam === \"Academy\");\n\n    if (captains.length) {\n      embed.addFields({\n        name: \"👑 Leadership\",\n        value: captains.map((p) => `**${p.roleInTeam}:** ${p.user.username} (${p.position})`).join(\"\\n\"),\n        inline: false,\n      });\n    }\n\n    for (const pos of POSITION_ORDER) {\n      const posPlayers = starters.filter((p) => p.position === pos);\n      if (posPlayers.length) {\n        embed.addFields({\n          name: `${POS_EMOJIS[pos] ?? \"👤\"} ${pos}s (${posPlayers.length})`,\n          value: posPlayers\n            .map((p) => `**${p.user.username}** — ⚽${p.goals}G / 🎯${p.assists}A / 📋${p.appearances}Apps`)\n            .join(\"\\n\"),\n          inline: false,\n        });\n      }\n    }\n\n    if (subs.length) {\n      embed.addFields({\n        name: \"🔄 Substitutes & Academy\",\n        value: subs.map((p) => `**${p.user.username}** (${p.position}${p.roleInTeam ? ` — ${p.roleInTeam}` : \"\"})`).join(\"\\n\"),\n        inline: false,\n      });\n    }\n\n    embed.setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/club/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  StringSelectMenuBuilder,\n  ComponentType,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"club\")\n    .setDescription(\"View a complete team hub with stats, history, and roster\")\n    .addStringOption((opt) =>\n      opt.setName(\"team\").setDescription(\"Team name\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const teamName = interaction.options.getString(\"team\", true);\n    const team = await teamService.getTeamByName(teamName);\n    if (!team) {\n      await interaction.editReply({ content: `❌ Team **${teamName}** not found.` });\n      return;\n    }\n    await showClubPage(interaction, team, \"stats\");\n  },\n};\n\nasync function showClubPage(interaction: CommandInteraction, team: Awaited<ReturnType<typeof teamService.getTeamByName>>, tab: string) {\n  if (!team) return;\n  let embed: EmbedBuilder;\n\n  switch (tab) {\n    case \"roster\": {\n      const posOrder = [\"Goalkeeper\", \"Defender\", \"Midfielder\", \"Forward\"];\n      embed = new EmbedBuilder().setTitle(`👥 ${team.name} — Roster`).setColor(\"#00AA00\");\n      for (const pos of posOrder) {\n        const filtered = team.players.filter((p) => p.position === pos);\n        if (filtered.length) embed.addFields({ name: `${pos}s (${filtered.length})`, value: filtered.map((p) => `**${p.user.username}**${p.roleInTeam ? ` — ${p.roleInTeam}` : \"\"} — ⚽${p.goals}G 🎯${p.assists}A`).join(\"\\n\"), inline: false });\n      }\n      break;\n    }\n    case \"history\": {\n      const matches = await matchService.getTeamMatches(team.id);\n      embed = new EmbedBuilder().setTitle(`📊 ${team.name} — Match History`).setColor(\"#00AA00\");\n      if (matches.length) {\n        const finished = matches.filter((m) => m.status === \"Finished\").slice(0, 10);\n        embed.setDescription(finished.length\n          ? finished.map((m) => {\n              const isHome = m.homeTeamId === team.id;\n              const score = isHome ? `${m.homeScore}-${m.awayScore}` : `${m.awayScore}-${m.homeScore}`;\n              const opponent = isHome ? m.awayTeam.name : m.homeTeam.name;\n              const result = isHome ? (m.homeScore > m.awayScore ? \"✅ W\" : m.homeScore < m.awayScore ? \"❌ L\" : \"🤝 D\") : (m.awayScore > m.homeScore ? \"✅ W\" : m.awayScore < m.homeScore ? \"❌ L\" : \"🤝 D\");\n              return `${result} | ${team.name} ${score} vs ${opponent}`;\n            }).join(\"\\n\")\n          : \"No finished matches.\"\n        );\n      } else {\n        embed.setDescription(\"No matches played yet.\");\n      }\n      break;\n    }\n    default: {\n      const ss = team.seasonTeams[team.seasonTeams.length - 1];\n      embed = new EmbedBuilder()\n        .setTitle(`🏟️ ${team.name} ${team.shortName ? `(${team.shortName})` : \"\"}`)\n        .setColor(\"#00AA00\")\n        .setDescription(team.description ?? \"No description.\")\n        .addFields(\n          { name: \"👤 Manager\", value: `<@${team.manager.discordId}>`, inline: true },\n          { name: \"👥 Squad\", value: `${team.players.length} players`, inline: true },\n          { name: \"🏆 Trophies\", value: `${team.trophies}`, inline: true }\n        );\n      if (ss) {\n        const gd = ss.goalsFor - ss.goalsAgainst;\n        embed.addFields({ name: \"📊 Season Record\", value: `**${ss.played}**PL | **${ss.wins}**W | **${ss.draws}**D | **${ss.losses}**L | GF:${ss.goalsFor} GA:${ss.goalsAgainst} GD:${gd >= 0 ? \"+\" : \"\"}${gd} | **${ss.points}pts**`, inline: false });\n      }\n      const top = [...team.players].sort((a, b) => b.goals - a.goals).slice(0, 3);\n      if (top.length) embed.addFields({ name: \"⚽ Top Scorers\", value: top.map((p, i) => `${i + 1}. **${p.user.username}** — ${p.goals}G`).join(\"\\n\"), inline: false });\n    }\n  }\n\n  const select = new StringSelectMenuBuilder().setCustomId(\"club_tabs\").setPlaceholder(\"Switch tab...\")\n    .addOptions(\n      { label: \"📊 Stats & Info\", value: \"stats\", emoji: \"📊\", default: tab === \"stats\" },\n      { label: \"👥 Roster\", value: \"roster\", emoji: \"👥\", default: tab === \"roster\" },\n      { label: \"📋 Match History\", value: \"history\", emoji: \"📋\", default: tab === \"history\" },\n    );\n\n  const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select);\n  const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n  const collector = reply.createMessageComponentCollector({ componentType: ComponentType.StringSelect, time: 120_000 });\n  collector.on(\"collect\", async (si) => {\n    if (si.user.id !== interaction.user.id) { await si.reply({ content: \"❌ Not your menu.\", ephemeral: true }); return; }\n    await si.deferUpdate();\n    const refreshed = await teamService.getTeamByName(team.name);\n    if (refreshed) await showClubPage(si as unknown as CommandInteraction, refreshed, si.values[0]);\n  });\n  collector.on(\"end\", async () => {\n    const dr = ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n    dr.components.forEach((c) => c.setDisabled(true));\n    await interaction.editReply({ components: [dr] }).catch(() => {});\n  });\n}\n\nexport default command;","src/commands/creatematch/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ChannelType,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"creatematch\")\n    .setDescription(\"Create a match with thread for live updates (Management/Referee)\")\n    .addStringOption((o) => o.setName(\"home\").setDescription(\"Home team\").setRequired(true))\n    .addStringOption((o) => o.setName(\"away\").setDescription(\"Away team\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"week\").setDescription(\"Matchweek number\").setRequired(false))\n    .addUserOption((o) => o.setName(\"referee\").setDescription(\"Referee\").setRequired(false))\n    .addBooleanOption((o) => o.setName(\"createthread\").setDescription(\"Create a match thread?\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) &&\n        !hasRole(interaction.member as never, RoleType.LeagueManagement) &&\n        !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Insufficient Permissions\", \"Need Staff role.\")] });\n      return;\n    }\n\n    const homeName = interaction.options.getString(\"home\", true);\n    const awayName = interaction.options.getString(\"away\", true);\n    const week = interaction.options.getInteger(\"week\");\n    const refUser = interaction.options.getUser(\"referee\");\n    const createThread = interaction.options.getBoolean(\"createthread\") ?? true;\n\n    const homeTeam = await teamService.getTeamByName(homeName);\n    const awayTeam = await teamService.getTeamByName(awayName);\n    if (!homeTeam || !awayTeam) {\n      await interaction.editReply({ content: \"❌ One or both teams not found.\" });\n      return;\n    }\n    if (homeTeam.id === awayTeam.id) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Invalid\", \"Cannot play itself.\")] });\n      return;\n    }\n\n    const activeSeason = await leagueService.getActiveSeason();\n    if (!activeSeason) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ No Active Season\", \"Start a season first.\")] });\n      return;\n    }\n\n    const match = await matchService.createMatch({\n      homeTeamId: homeTeam.id,\n      awayTeamId: awayTeam.id,\n      seasonId: activeSeason.id,\n      refereeId: refUser?.id,\n    });\n\n    // Update matchweek\n    if (week) {\n      await (await import(\"../../database/prisma.js\")).prisma.match.update({\n        where: { id: match.id },\n        data: { matchweek: week },\n      });\n    }\n\n    // Create thread\n    let threadInfo = \"No thread created.\";\n    if (createThread && interaction.channel && interaction.channel.type === ChannelType.GuildText) {\n      try {\n        const thread = await interaction.channel.threads.create({\n          name: `⚽ ${homeTeam.name} vs ${awayTeam.name}${week ? ` (GW${week})` : \"\"}`,\n          reason: \"Match thread for live updates\",\n        });\n        await thread.send(`⚽ **${homeTeam.name}** vs **${awayTeam.name}**\\n📅 ${activeSeason.name}${refUser ? `\\n👨‍⚖️ Referee: <@${refUser.id}>` : \"\"}\\n\\nUse **/goal**, **/assist**, **/yellow**, **/red** in this thread to log events!`);\n        await (await import(\"../../database/prisma.js\")).prisma.match.update({\n          where: { id: match.id },\n          data: { threadId: thread.id },\n        });\n        threadInfo = `📝 Thread created: ${thread}`;\n      } catch { threadInfo = \"⚠️ Could not create thread.\"; }\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"⚽ Match Created!\")\n      .setColor(\"#00AA00\")\n      .addFields(\n        { name: \"🏠 Home\", value: homeTeam.name, inline: true },\n        { name: \"🆚 vs\", value: awayTeam.name, inline: true },\n        { name: \"📅 Week\", value: week ? `GW${week}` : \"TBD\", inline: true },\n        { name: \"👨‍⚖️ Referee\", value: refUser ? `<@${refUser.id}>` : \"TBD\", inline: true },\n        { name: \"🆔 Match ID\", value: match.id.slice(0, 8), inline: true },\n        { name: \"📋 Status\", value: \"🟢 Scheduled\", inline: true },\n        { name: \"📎 Thread\", value: threadInfo, inline: false },\n      )\n      .setFooter({ text: \"Use /match start or /fulltime when ready\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/goal/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"goal\")\n    .setDescription(\"Quick log a goal during a live match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"scorer\").setDescription(\"Player who scored\").setRequired(true))\n    .addUserOption((o) => o.setName(\"assist\").setDescription(\"Player who assisted\").setRequired(false))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute scored\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const scorer = interaction.options.getUser(\"scorer\", true);\n    const assist = interaction.options.getUser(\"assist\");\n    const minute = interaction.options.getInteger(\"minute\");\n\n    const player = await prisma.player.findUnique({ where: { discordId: scorer.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Scorer not registered.\" }); return; }\n\n    await prisma.matchGoal.create({ data: { matchId, playerId: player.id, minute } });\n    await prisma.player.update({ where: { id: player.id }, data: { goals: { increment: 1 }, appearances: { increment: 1 } } });\n    await updatePlayerSeasonStat(player.id, matchId, \"goals\");\n\n    let assistText = \"\";\n    if (assist) {\n      const aPlayer = await prisma.player.findUnique({ where: { discordId: assist.id } });\n      if (aPlayer) {\n        await prisma.matchAssist.create({ data: { matchId, playerId: aPlayer.id, minute } });\n        await prisma.player.update({ where: { id: aPlayer.id }, data: { assists: { increment: 1 } } });\n        assistText = `\\n🎯 **Assist:** <@${assist.id}>`;\n      }\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"⚽ GOAL!\")\n      .setColor(\"#00AA00\")\n      .setDescription(`**<@${scorer.id}>** scores!${assistText}`)\n      .addFields(\n        { name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true },\n        { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true },\n      )\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nasync function updatePlayerSeasonStat(playerId: string, matchId: string, field: string) {\n  const match = await prisma.match.findUnique({ where: { id: matchId }, select: { seasonId: true } });\n  if (!match) return;\n  const stat = await prisma.playerSeasonStats.findUnique({\n    where: { playerId_seasonId: { playerId, seasonId: match.seasonId } },\n  });\n  if (stat) {\n    await prisma.playerSeasonStats.update({ where: { id: stat.id }, data: { [field]: { increment: 1 } } });\n  }\n}\n\nexport default command;","src/commands/assist/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"assist\")\n    .setDescription(\"Quick log an assist during a live match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player who assisted\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const target = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getInteger(\"minute\");\n    const player = await prisma.player.findUnique({ where: { discordId: target.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n    await prisma.matchAssist.create({ data: { matchId, playerId: player.id, minute } });\n    await prisma.player.update({ where: { id: player.id }, data: { assists: { increment: 1 } } });\n    const embed = new EmbedBuilder().setTitle(\"🎯 Assist Logged\").setColor(\"#00AAFF\")\n      .setDescription(`**<@${target.id}>** provided the assist!`)\n      .addFields({ name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true }, { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true })\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/yellow/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"yellow\")\n    .setDescription(\"Log a yellow card during a match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player booked\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute\").setRequired(false))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const target = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getInteger(\"minute\");\n    const reason = interaction.options.getString(\"reason\");\n    const player = await prisma.player.findUnique({ where: { discordId: target.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n    await prisma.matchCard.create({ data: { matchId, playerId: player.id, type: \"Yellow\", minute, reason } });\n    await prisma.player.update({ where: { id: player.id }, data: { yellowCards: { increment: 1 } } });\n    const embed = new EmbedBuilder().setTitle(\"🟨 Yellow Card\").setColor(\"#FFAA00\")\n      .setDescription(`**<@${target.id}>** has been booked!`)\n      .addFields({ name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true }, { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true }, { name: \"📝 Reason\", value: reason ?? \"Foul\", inline: false })\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/red/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"red\")\n    .setDescription(\"Log a red card during a match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player sent off\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute\").setRequired(false))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const target = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getInteger(\"minute\");\n    const reason = interaction.options.getString(\"reason\");\n    const player = await prisma.player.findUnique({ where: { discordId: target.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n    await prisma.matchCard.create({ data: { matchId, playerId: player.id, type: \"Red\", minute, reason } });\n    await prisma.player.update({ where: { id: player.id }, data: { redCards: { increment: 1 } } });\n    const embed = new EmbedBuilder().setTitle(\"🟥 RED CARD!\").setColor(\"#FF0000\")\n      .setDescription(`**<@${target.id}>** has been sent off!`)\n      .addFields({ name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true }, { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true }, { name: \"📝 Reason\", value: reason ?? \"Serious foul play\", inline: false })\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/fulltime/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"fulltime\")\n    .setDescription(\"Conclude a match — freeze log, update standings, post result\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"home_score\").setDescription(\"Home score\").setRequired(true).setMinValue(0))\n    .addIntegerOption((o) => o.setName(\"away_score\").setDescription(\"Away score\").setRequired(true).setMinValue(0))\n    .addUserOption((o) => o.setName(\"motm\").setDescription(\"Man of the Match\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const homeScore = interaction.options.getInteger(\"home_score\", true);\n    const awayScore = interaction.options.getInteger(\"away_score\", true);\n    const motmUser = interaction.options.getUser(\"motm\");\n\n    try {\n      const match = await matchService.finishMatch(matchId, { homeScore, awayScore });\n\n      // Record MOTM\n      if (motmUser) {\n        const motmPlayer = await prisma.player.findUnique({ where: { discordId: motmUser.id } });\n        if (motmPlayer) {\n          await prisma.matchMvp.create({ data: { matchId, playerId: motmPlayer.id, reason: \"Man of the Match\" } });\n          await prisma.player.update({ where: { id: motmPlayer.id }, data: { mvps: { increment: 1 } } });\n        }\n      }\n\n      // Resolve predictions\n      await predictionService.resolvePredictions(matchId);\n\n      // Auto-post news\n      const fullMatch = await prisma.match.findUnique({\n        where: { id: match.id },\n        include: {\n          homeTeam: true, awayTeam: true,\n          goals: { include: { player: { include: { user: true } } } },\n          mvps: { include: { player: { include: { user: true } } } },\n        },\n      });\n\n      if (fullMatch && interaction.guild) {\n        const scorers = fullMatch.goals.map((g) => `${g.player.user.username}${g.minute ? ` (${g.minute}')` : \"\"}`);\n        const mvp = fullMatch.mvps[0]?.player.user.username;\n        await newsService.announceMatchResult(interaction.client as ExtendedClient, {\n          guildId: interaction.guild.id,\n          homeTeam: fullMatch.homeTeam.name,\n          awayTeam: fullMatch.awayTeam.name,\n          homeScore: fullMatch.homeScore,\n          awayScore: fullMatch.awayScore,\n          scorers, mvp, matchId: match.id,\n        });\n        for (const g of fullMatch.goals) await newsService.checkMilestones(interaction.client as ExtendedClient, interaction.guild.id, g.playerId);\n        if (fullMatch.mvps[0]) await newsService.checkMilestones(interaction.client as ExtendedClient, interaction.guild.id, fullMatch.mvps[0].playerId);\n      }\n\n      // Archive thread\n      if (fullMatch?.threadId && interaction.channel) {\n        try {\n          const thread = await interaction.channel.client.channels.fetch(fullMatch.threadId);\n          if (thread?.isThread()) await thread.setArchived(true);\n        } catch { /* ok */ }\n      }\n\n      const result = homeScore > awayScore ? \"🏠 Home Win\" : awayScore > homeScore ? \"🚗 Away Win\" : \"🤝 Draw\";\n      const embed = new EmbedBuilder()\n        .setTitle(\"✅ Full-Time!\")\n        .setColor(\"#00AA00\")\n        .setDescription(`**${match.homeTeamId}** ${homeScore} - ${awayScore} **${match.awayTeamId}**\\n\\n📊 **${result}**`)\n        .addFields(\n          { name: \"🏆 MOTM\", value: motmUser ? `<@${motmUser.id}>` : \"Not selected\", inline: true },\n          { name: \"📊 Status\", value: \"✅ Finished\", inline: true },\n        )\n        .setFooter({ text: \"Standings & predictions updated • Legacy Football Championship\" }).setTimestamp();\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Fulltime Error]\", error);\n      await interaction.editReply({ content: \"❌ Failed to conclude match.\" });\n    }\n  },\n};\nexport default command;"};
